-- ===== 023_financial_memory_graph.sql =====
-- Migration 023: Financial Memory Graph (FMG)
-- Permanent, intelligent financial memory for every user.
-- Never deletes historical data. Builds knowledge, not just records.

-- ── 1. Memories: beliefs, preferences, rules, lessons, biases ────────────────
CREATE TABLE IF NOT EXISTS fmg_memories (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id          UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  type             TEXT NOT NULL
    CHECK (type IN ('belief','preference','rule','lesson','bias','goal','insight')),
  content          TEXT NOT NULL,
  source           TEXT NOT NULL DEFAULT 'conversation'
    CHECK (source IN ('conversation','behavior','manual','system')),
  confidence       REAL NOT NULL DEFAULT 1.0 CHECK (confidence BETWEEN 0 AND 1),
  times_reinforced INT  NOT NULL DEFAULT 1,
  is_active        BOOLEAN NOT NULL DEFAULT TRUE,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_fmg_memories_user_active
  ON fmg_memories (user_id, is_active, type);

-- ── 2. Behavioral patterns with confidence evolution ─────────────────────────
CREATE TABLE IF NOT EXISTS fmg_behavioral_patterns (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id           UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  pattern_key       TEXT NOT NULL,      -- e.g. 'sells_during_drops', 'buys_after_rallies'
  description       TEXT NOT NULL,
  confidence        REAL NOT NULL DEFAULT 0.5 CHECK (confidence BETWEEN 0 AND 1),
  times_observed    INT  NOT NULL DEFAULT 1,
  is_positive       BOOLEAN NOT NULL DEFAULT FALSE,
  first_detected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_detected_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, pattern_key)
);

CREATE INDEX IF NOT EXISTS idx_fmg_patterns_user
  ON fmg_behavioral_patterns (user_id, confidence DESC);

-- ── 3. Timeline events: milestones, emotional events, decisions ───────────────
CREATE TABLE IF NOT EXISTS fmg_events (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  event_type  TEXT NOT NULL
    CHECK (event_type IN (
      'milestone','emotional','decision','first_investment',
      'goal_achieved','goal_changed','pattern_detected','learning'
    )),
  title       TEXT NOT NULL,
  description TEXT,
  metadata    JSONB NOT NULL DEFAULT '{}',
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_fmg_events_user_time
  ON fmg_events (user_id, occurred_at DESC);

-- ── 4. Portfolio value snapshots (one per user per day) ──────────────────────
CREATE TABLE IF NOT EXISTS fmg_portfolio_snapshots (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  snapshot_date   DATE NOT NULL,
  total_value     REAL NOT NULL DEFAULT 0,
  positions_count INT  NOT NULL DEFAULT 0,
  top_sector      TEXT,
  sector_weights  JSONB NOT NULL DEFAULT '{}',   -- {"Tecnología": 0.42, ...}
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, snapshot_date)
);

CREATE INDEX IF NOT EXISTS idx_fmg_snapshots_user_date
  ON fmg_portfolio_snapshots (user_id, snapshot_date DESC);

-- ── RLS ──────────────────────────────────────────────────────────────────────
ALTER TABLE fmg_memories              ENABLE ROW LEVEL SECURITY;
ALTER TABLE fmg_behavioral_patterns   ENABLE ROW LEVEL SECURITY;
ALTER TABLE fmg_events                ENABLE ROW LEVEL SECURITY;
ALTER TABLE fmg_portfolio_snapshots   ENABLE ROW LEVEL SECURITY;

CREATE POLICY fmg_memories_self ON fmg_memories
  FOR ALL USING (user_id = auth.uid());

CREATE POLICY fmg_patterns_self ON fmg_behavioral_patterns
  FOR ALL USING (user_id = auth.uid());

CREATE POLICY fmg_events_self ON fmg_events
  FOR ALL USING (user_id = auth.uid());

CREATE POLICY fmg_snapshots_self ON fmg_portfolio_snapshots
  FOR ALL USING (user_id = auth.uid());


-- ===== 024_investor_progress_engine.sql =====
-- Migration 024: Investor Progress Engine (Fase 1 — motor de cálculo)
-- Reutiliza fmg_events como timeline permanente de hitos (idempotente vía
-- milestone_key) en vez de crear una tabla paralela. Agrega fmg_annual_reports
-- porque el resumen anual sí debe congelarse una vez pasa el año, no
-- recalcularse con datos futuros.

-- ── 1. Hitos: reutilizar fmg_events con clave idempotente ────────────────────
ALTER TABLE fmg_events ADD COLUMN IF NOT EXISTS milestone_key TEXT;

CREATE UNIQUE INDEX IF NOT EXISTS idx_fmg_events_milestone_key
  ON fmg_events (user_id, milestone_key) WHERE milestone_key IS NOT NULL;

-- ── 2. Resumen anual congelado ────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS fmg_annual_reports (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  year         INT NOT NULL,
  report       JSONB NOT NULL DEFAULT '{}',
  finalized    BOOLEAN NOT NULL DEFAULT FALSE,  -- true una vez termina el año calendario
  generated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, year)
);

CREATE INDEX IF NOT EXISTS idx_fmg_annual_reports_user
  ON fmg_annual_reports (user_id, year DESC);

-- ── RLS ──────────────────────────────────────────────────────────────────────
-- Explícito owner + service_role, siguiendo 019_fix_portfolio_rls.sql — sin la
-- policy de service_role, el propio backend queda bloqueado (incidente ya
-- vivido una vez en este proyecto con user_portfolio/user_paper_trading).
ALTER TABLE fmg_annual_reports ENABLE ROW LEVEL SECURITY;

CREATE POLICY fmg_annual_reports_self ON fmg_annual_reports
  FOR ALL USING (user_id = auth.uid());

CREATE POLICY fmg_annual_reports_service_role ON fmg_annual_reports
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 025_duo_bidirectional_link.sql =====
-- Migration 025: Duo Plan bidirectional link
-- Today only the primary account knows the secondary's email
-- (duo_secondary_email). The secondary has no way to know who invited them.
-- Adds a two-way link so either side can look up its partner directly.

ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS duo_primary_user_id   UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS duo_secondary_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL;


-- ===== 026_valuation_alert_state.sql =====
-- Migration 026: valuation alert state
-- Tracks the last valuation tier (Muy cara / Cara / Precio justo / Buen rango /
-- Barata) notified per user+ticker, so the weekly valuation push only fires
-- when the tier actually changes instead of repeating the same message forever.

CREATE TABLE IF NOT EXISTS valuation_alert_state (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  ticker     TEXT NOT NULL,
  last_tier  TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, ticker)
);

CREATE INDEX IF NOT EXISTS idx_valuation_alert_state_user
  ON valuation_alert_state (user_id);

ALTER TABLE valuation_alert_state ENABLE ROW LEVEL SECURITY;

CREATE POLICY valuation_alert_state_self ON valuation_alert_state
  FOR ALL USING (user_id = auth.uid());


-- ===== 027_financial_profile_and_library.sql =====
-- Migration 027: structured Financial Profile + Personal Financial Library
-- Promotes the fields every agent/habit job actually reads out of the
-- quiz_answers JSONB blob into typed, queryable columns, and adds the
-- permanent library (saved analyses, notes, theses, uploads).

-- ── 1. Structured profile fields (additive, non-breaking) ────────────────────
ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS net_worth_usd                NUMERIC,
  ADD COLUMN IF NOT EXISTS monthly_expenses_usd         NUMERIC,
  ADD COLUMN IF NOT EXISTS currency                     TEXT DEFAULT 'USD',
  ADD COLUMN IF NOT EXISTS preferred_language            TEXT DEFAULT 'es',
  ADD COLUMN IF NOT EXISTS investing_style               TEXT
    CHECK (investing_style IN ('value','growth','dividend','index','momentum','not_set'))
    DEFAULT 'not_set',
  ADD COLUMN IF NOT EXISTS time_horizon_years            INT,
  ADD COLUMN IF NOT EXISTS financial_freedom_target_usd  NUMERIC;

-- ── 2. Financial goals — 1:many, don't cram into a column ────────────────────
CREATE TABLE IF NOT EXISTS user_financial_goals (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  goal_type    TEXT NOT NULL CHECK (goal_type IN ('retirement','house','freedom_number','education','emergency_fund','custom')),
  label        TEXT,
  target_usd   NUMERIC,
  target_date  DATE,
  is_primary   BOOLEAN NOT NULL DEFAULT FALSE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_user_financial_goals_user ON user_financial_goals (user_id);

-- ── 3. Sector preferences — declared + behavior-inferred weight ──────────────
CREATE TABLE IF NOT EXISTS user_sector_preferences (
  user_id  UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  sector   TEXT NOT NULL,
  weight   REAL NOT NULL DEFAULT 1.0,
  source   TEXT NOT NULL DEFAULT 'declared' CHECK (source IN ('declared','inferred')),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, sector)
);

-- ── 4. Personal Financial Library ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS library_items (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  item_type    TEXT NOT NULL CHECK (item_type IN
