-- ===== 033_security_events.sql =====
-- ============================================================================
-- 033_security_events.sql
--
-- Audit trail for authentication abuse: failed logins, lockouts, password
-- reset abuse. Written by app/core/security.py — never blocks a request if
-- this insert fails (best-effort logging), but gives a real queryable trail
-- instead of only ephemeral log lines for incident response / abuse review.
-- ============================================================================

CREATE TABLE IF NOT EXISTS security_events (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_type  TEXT NOT NULL,       -- 'login_failed' | 'login_lockout' | 'password_reset_code_failed' | 'password_reset_lockout' | ...
  email       TEXT,
  ip_address  TEXT,
  user_id     UUID,                -- nullable: most brute-force events happen pre-auth, with no known user_id yet
  detail      TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_security_events_email      ON security_events(email, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_security_events_ip         ON security_events(ip_address, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_security_events_type_time  ON security_events(event_type, created_at DESC);

-- No end-user ever reads this table directly (no app UI surfaces it) — it's
-- an internal/admin audit log. Only the backend's service_role writes or
-- reads it; RLS enabled with zero user-facing policies is intentional here
-- (mirrors benchmark_cohort_stats' pattern from 032), with an explicit
-- service_role policy per this project's now-standard defensive pattern.
ALTER TABLE security_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: security events" ON security_events;
CREATE POLICY "Service: security events" ON security_events
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 034_research_job_queue.sql =====
-- ============================================================================
-- 034_research_job_queue.sql
--
-- Redesigns Deep Research from a fire-and-forget asyncio.create_task (owned
-- by whichever web request happened to call /start, and lost entirely if
-- that process restarts) into a real persistent job queue: jobs are claimed
-- atomically (FOR UPDATE SKIP LOCKED — the standard Postgres queue pattern,
-- safe for any number of concurrent claimers) by the separate, single-
-- purpose `worker.py` process, with a heartbeat so a crashed/restarted
-- worker's in-flight jobs are detected and retried automatically instead of
-- being stuck at "researching" forever.
-- ============================================================================

ALTER TABLE research_jobs ADD COLUMN IF NOT EXISTS claimed_by TEXT;
ALTER TABLE research_jobs ADD COLUMN IF NOT EXISTS claimed_at TIMESTAMPTZ;
ALTER TABLE research_jobs ADD COLUMN IF NOT EXISTS heartbeat_at TIMESTAMPTZ;
ALTER TABLE research_jobs ADD COLUMN IF NOT EXISTS attempts INTEGER NOT NULL DEFAULT 0;
ALTER TABLE research_jobs ADD COLUMN IF NOT EXISTS max_attempts INTEGER NOT NULL DEFAULT 3;
ALTER TABLE research_jobs ADD COLUMN IF NOT EXISTS cancel_requested BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE research_jobs ADD COLUMN IF NOT EXISTS refunded BOOLEAN NOT NULL DEFAULT false;

-- 'cancelled' joins the existing pending/researching/completed/failed set.
ALTER TABLE research_jobs DROP CONSTRAINT IF EXISTS research_jobs_status_check;
ALTER TABLE research_jobs ADD CONSTRAINT research_jobs_status_check
  CHECK (status IN ('pending', 'researching', 'completed', 'failed', 'cancelled'));

CREATE INDEX IF NOT EXISTS idx_research_jobs_claim ON research_jobs(status, created_at) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS idx_research_jobs_heartbeat ON research_jobs(status, heartbeat_at) WHERE status = 'researching';

-- Atomic claim: the only correct way to let N worker processes pull from the
-- same queue without two of them ever grabbing the same job. SKIP LOCKED
-- means a claimer never blocks waiting on a row another claimer already has
-- locked — it just moves on to the next eligible row. This one function is
-- what makes horizontal scaling of the worker safe: running 5 worker
-- instances instead of 1 requires zero code changes, just more callers of
-- this same function.
CREATE OR REPLACE FUNCTION claim_research_job(p_worker_id TEXT)
RETURNS SETOF research_jobs
LANGUAGE plpgsql
AS $$
DECLARE
  claimed_id UUID;
BEGIN
  SELECT id INTO claimed_id
  FROM research_jobs
  WHERE status = 'pending'
  ORDER BY created_at ASC
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF claimed_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  UPDATE research_jobs
  SET status = 'researching',
      claimed_by = p_worker_id,
      claimed_at = NOW(),
      heartbeat_at = NOW(),
      attempts = attempts + 1
  WHERE id = claimed_id
  RETURNING *;
END;
$$;

-- Reclaim jobs whose worker died mid-run: a heartbeat older than the
-- threshold means the process that claimed it is gone (or wedged) without
-- ever reaching a terminal state. Requeue to 'pending' if attempts remain,
-- else mark 'failed' so it stops being retried forever and becomes eligible
-- for the refund path in research_service.reap_stale_jobs().
CREATE OR REPLACE FUNCTION reap_stale_research_jobs(p_stale_after_seconds INT DEFAULT 600)
RETURNS SETOF research_jobs
LANGUAGE plpgsql
AS $$
BEGIN
  RETURN QUERY
  UPDATE research_jobs
  SET status = CASE WHEN attempts < max_attempts THEN 'pending' ELSE 'failed' END,
      error = CASE WHEN attempts >= max_attempts THEN 'Se agotaron los intentos tras una interrupción del servidor.' ELSE error END,
      claimed_by = NULL,
      claimed_at = NULL,
      completed_at = CASE WHEN attempts >= max_attempts THEN NOW() ELSE completed_at END
  WHERE status = 'researching'
    AND heartbeat_at < NOW() - (p_stale_after_seconds || ' seconds')::interval
  RETURNING *;
END;
$$;

GRANT EXECUTE ON FUNCTION claim_research_job(TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION reap_stale_research_jobs(INT) TO service_role;


-- ===== 035_atomic_account_deletion.sql =====
-- ============================================================================
-- 035_atomic_account_deletion.sql
--
-- Account deletion previously looped over ~35 tables in Python, each with
-- its own try/except and no rollback — a failure partway through left the
-- user's auth account deleted (email freed for reuse) while some tables
-- still held orphaned rows keyed to a user_id that no longer mapped to any
-- account. This function moves the DATA deletion into a single Postgres
-- function body, which Postgres runs as one transaction: if any DELETE
-- fails, ALL of them roll back together — there is no partial-deletion
-- state anymore, only "fully deleted" or "fully unchanged" (with a clear
-- exception the Python caller can surface to the user and retry).
--
-- The auth.users row itself is deleted separately by the Python caller
-- (auth.admin.delete_user — a Supabase Admin API call, not a plain SQL
-- statement, so it can't live inside this same transaction) — but doing
-- data deletion atomically first, then the auth user, means a failure on
-- the SECOND step just leaves a fully-data-wiped account that still exists
-- and can be deleted again (idempotent retry), instead of a half-wiped one.
--
-- Keep this table list in sync with _USER_DATA_TABLES in
-- backend/app/api/routes/auth.py — they must name the same tables.
--
-- Implementation note: most of these tables have a `user_id UUID` column,
-- but two (support_tickets, investment_decisions) use `user_id TEXT`
-- instead, and portfolio_positions' exact schema could not be confirmed
-- from application code alone (see migrations/032_rls_hardening.sql's own
-- note on it) — its existence/column name is inferred, not verified. Two
-- defensive choices follow directly from that uncertainty:
--   1. Every comparison casts BOTH sides to text (`user_id::text = p_user_id::text`)
--      so this works identically whether a given table's user_id is UUID or TEXT,
--      without needing a table-by-table special case.
--   2. Each DELETE runs in its own nested BEGIN/EXCEPTION block (an implicit
--      Postgres savepoint) that specifically catches undefined_table/
--      undefined_column — a genuinely unexpected schema mismatch for ONE
--      table degrades gracefully (skipped, logged via RAISE WARNING) rather
--      than rolling back the ENTIRE deletion for every other table too.
--      Any OTHER kind of error (a real constraint violation, a connection
--      issue) is deliberately NOT caught here and propagates to roll back
--      the whole transaction — that's still exactly the atomicity guarantee
--      this migration exists to provide, just scoped to real failures
--      instead of also including "a table's schema wasn't what we assumed."
-- ============================================================================

CREATE OR REPLACE FUNCTION delete_user_data(p_user_id UUID)
RETURNS VOID
LANGUAGE plpgsql
AS $$
DECLARE
  tbl TEXT;
  tables TEXT[] := ARRAY[
    'user_profiles', 'user_portfolio', 'portfolio_positions', 'user_paper_trading',
    'user_daily_usage', 'web_push_subscriptions', 'chat_history',
    'notifications', 'watchlist', 'notification_preferences',
    'notification_log', 'notification_analytics', 'investment_decisions',
    'support_tickets', 'user_feedback', 'price_alerts', 'pending_actions',
    'upsell_dismissals', 'upsell_events', 'brokerage_connections',
    'voice_call_transcripts', 'user_financial_goals', 'user_sector_preferences',
    'library_items', 'habit_engagement',
    'fmg_memories', 'fmg_behavioral_patterns', 'fmg_events',
    'fmg_portfolio_snapshots', 'fmg_annual_reports',
    'valuation_alert_state', 'thesis_drift_state',
    'clip_likes', 'clip_saves', 'clip_views', 'clip_comments',
    'research_jobs', 'research_reports', 'security_events'
  ];
BEGIN
  FOREACH tbl IN ARRAY tables LOOP
    BEGIN
      EXECUTE format('DELETE FROM %I WHERE user_id::text = $1', tbl) USING p_user_id::text;
    EXCEPTION
      WHEN undefined_table OR undefined_column THEN
        RAISE WARNING 'delete_user_data: skipped % for % — table/column schema unexpected (%)', tbl, p_user_id, SQLERRM;
    END;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION delete_user_data(UUID) TO service_role;


-- ===== 036_major_news_events.sql =====
-- ============================================================================
-- 036_major_news_events.sql
--
-- Tracks the "big event" push alerts sent by worker.py's job_major_news_alert
-- (geopolitical tensions, macro indicators, major corporate news, major
-- statements/deals from big-company leaders — never analyst opinions or
-- price-target changes). Capped at 3 per calendar day
-- (ET), shared across ALL users (one event = one row here, then fanned out
-- to everyone), so this table is what makes that daily cap durable across
-- worker restarts/redeploys — an in-memory or Redis-only counter would reset
-- on every deploy, exactly like the price-alert dedup bug fixed earlier.
-- ============================================================================

CREATE TABLE IF NOT EXISTS major_news_events (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_date    DATE NOT NULL,       -- ET calendar day this counts against (max 3/day)
  headline_hash TEXT NOT NULL,       -- md5 of the headline — dedup so the same story isn't re-sent same day
  headline      TEXT NOT NULL,
  category      TEXT NOT NULL,       -- 'geopolitics' | 'macro' | 'corporate' | 'leadership'
  push_body     TEXT NOT NULL,
  sent_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_major_news_events_date ON major_news_events(event_date);
CREATE UNIQUE INDEX IF NOT EXISTS idx_major_news_events_date_hash
  ON major_news_events(event_date, headline_hash);

-- Internal/system table — no end-user ever reads it directly. Only the
-- backend's service_role writes or reads it; RLS enabled with zero
-- user-facing policies is intentional (mirrors security_events' pattern
-- from 033).
ALTER TABLE major_news_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: major news events" ON major_news_events;
CREATE POLICY "Service: major news events" ON major_news_events
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 037_llm_usage_log.sql =====
-- ============================================================================
-- 037_llm_usage_log.sql
--
-- Structured, queryable log of every Claude API call's token usage and cost —
-- recommendation #18/#19 of the cost-optimization architecture. Previously
-- cost was only visible as unstructured text in worker.py's
-- "LLM ...: in=%d out=%d cost=$%.5f" log lines, which can't be queried or
-- aggregated per-user. This table is what makes #19 (cost per user) and any
-- future per-endpoint cost dashboard possible.
-- ============================================================================

CREATE TABLE IF NOT EXISTS llm_usage_log (
  id                          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id                     UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  endpoint                    TEXT NOT NULL,        -- e.g. 'chat_stream', 'monthly_report', 'price_alert_why'
  model                       TEXT NOT NULL,
  input_tokens                INTEGER NOT NULL DEFAULT 0,
  output_tokens                INTEGER NOT NULL DEFAULT 0,
  cache_creation_input_tokens INTEGER NOT NULL DEFAULT 0,
  cache_read_input_tokens    INTEGER NOT NULL DEFAULT 0,
  cost_usd                    NUMERIC(10, 6) NOT NULL DEFAULT 0,
  created_at                  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_llm_usage_log_user_created ON llm_usage_log(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_llm_usage_log_endpoint_created ON llm_usage_log(endpoint, created_at DESC);

-- Internal/system table — no end-user ever reads it directly (only admin
-- aggregation queries via service_role). Mirrors the RLS pattern from
-- 033_security_events.sql / 036_major_news_events.sql.
ALTER TABLE llm_usage_log ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: llm usage log" ON llm_usage_log;
CREATE POLICY "Service: llm usage log" ON llm_usage_log
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 038_reset_trial_window_for_existing_users.sql =====
-- ============================================================================
-- 038_reset_trial_window_for_existing_users.sql
--
-- One-time data backfill (NOT a schema change): resets the 30-day free-
-- premium trial window to start today for every existing non-premium user,
-- per product decision on 2026-07-16 — "starting today, all existing users
-- and all new signups get 30 days of free premium."
--
-- Existing users already had trial_started_at set from signup (previously a
-- 90-day window); under the current 30-day rule that window has already
-- expired for most of them. This resets it to NOW() so everyone gets a
-- fresh 30 days from today, matching what new signups already get
-- automatically (trial_started_at is set lazily on first /status or
-- /start-trial call — see billing.py get_status and sync.py start_trial).
--
-- Paying users (subscription_tier = 'premium') are left untouched — they
-- don't need a trial window at all.
--
-- IMPORTANT: this is a one-time operation, not idempotent schema. Run it
-- ONCE manually in the Supabase SQL editor. Do NOT wire it into any
-- automated migration runner — running it again would reset everyone's
-- trial clock a second time.
-- ============================================================================

UPDATE user_profiles
SET trial_started_at = NOW()
WHERE subscription_tier IS DISTINCT FROM 'premium';


-- ===== 039_investment_journal.sql =====
-- Migration 039: Investment Journal
-- Append-only log of investment theses: every time Arthur generates a
-- full Premium fundamental analysis ("Analízame X"), the real numbers
-- (price, intrinsic value, scorecard) and the full narrative reply are
-- saved so the user can revisit the thesis later and compare it against
-- reality — unlike thesis_drift_state (migration 028), this is NOT a
-- dedup/state table: it accumulates one row per analysis over time.

CREATE TABLE IF NOT EXISTS investment_theses (
  id                       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id                  UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  ticker                   TEXT NOT NULL,
  company_name             TEXT,
  price_at_creation        NUMERIC(14,4),
  intrinsic_value_base     NUMERIC(14,4),
  intrinsic_value_expected NUMERIC(14,4),
  margin_of_safety_pct     NUMERIC(8,2),
  thesis_scores            JSONB,
  thesis_text              TEXT NOT NULL,
  created_at               TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_investment_theses_user_ticker ON investment_theses (user_id, ticker, created_at DESC);

ALTER TABLE investment_theses ENABLE ROW LEVEL SECURITY;

CREATE POLICY investment_theses_self ON investment_theses FOR ALL USING (user_id = auth.uid());


