-- ===== 051_notification_queue.sql =====
-- Migration 051: Notification delivery queue
-- Lets any job enqueue a push for delivery a few minutes in the future
-- instead of sending it immediately. First use: spacing out individual
-- per-stock price-mover alerts (job_portfolio_alerts) ~5 minutes apart so a
-- user with 3 simultaneous movers doesn't get 3 notifications in the same
-- second. job_dispatch_notification_queue (worker.py) polls this every 60s.
--
-- Also adds the AI-insight monthly quota counters used by the new
-- job_ai_insight_scan ("La IA encontró algo") — same migration since both
-- ship together.

CREATE TABLE IF NOT EXISTS notification_queue (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  category      TEXT NOT NULL,
  title         TEXT NOT NULL,
  body          TEXT NOT NULL,
  data          JSONB NOT NULL DEFAULT '{}'::jsonb,
  scheduled_for TIMESTAMPTZ NOT NULL,
  sent_at       TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_notification_queue_pending
  ON notification_queue(scheduled_for) WHERE sent_at IS NULL;

ALTER TABLE notification_queue ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: notification queue" ON notification_queue;
CREATE POLICY "Service: notification queue" ON notification_queue
  FOR ALL TO service_role USING (true) WITH CHECK (true);

ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS ai_insight_count INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS ai_insight_month TEXT;


-- ===== 052_referral_reward_tiers.sql =====
-- Migration 052: tiered referral rewards
--
-- The referral program used to pay a flat 14 days to the referrer on every
-- successful referral, uncapped. Replaced with 3 one-time milestone tiers:
--   1 friend  -> +14 days premium
--   2 friends -> +14 days premium, +1 free 1:1 session
--   3 friends -> +30 days premium, +1 free 1:1 session, +1 free deep research
-- referral_reward_tier tracks the highest tier already paid out, so a
-- referrer's count passing a threshold only pays that tier once.

ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS referral_reward_tier INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS free_1on1_sessions INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS free_deep_research_credits INTEGER NOT NULL DEFAULT 0;


-- ===== 053_cash_holdings.sql =====
-- Migration 053: cash holdings
--
-- Lets a user record cash they hold outside of stock positions (CETES,
-- parked in a bank account, bonds, or something else) so it counts toward
-- their real total portfolio value — previously the portfolio total only
-- ever summed stock/crypto positions.

CREATE TABLE IF NOT EXISTS cash_holdings (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  amount      NUMERIC NOT NULL CHECK (amount >= 0),
  currency    TEXT NOT NULL DEFAULT 'USD',
  instrument  TEXT NOT NULL DEFAULT 'other' CHECK (instrument IN ('cetes', 'bank', 'bonds', 'other')),
  label       TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_cash_holdings_user ON cash_holdings (user_id);

ALTER TABLE cash_holdings ENABLE ROW LEVEL SECURITY;

CREATE POLICY cash_holdings_self ON cash_holdings
  FOR ALL USING (user_id = auth.uid());


-- ===== 054_dividend_income.sql =====
-- Migration 054: dividend income ledger
--
-- Records dividend payments the user actually received on positions they
-- held on the payment date — worker.py's job_dividend_income (a standalone
-- daily job, independent of subscription tier or push-notification prefs)
-- writes one row here the day a dividend is paid, computed as shares_held *
-- per_share_amount. This is forward-tracking only: dividends paid before
-- this feature shipped are never backfilled/guessed, since we have no
-- reliable record of exactly how many shares the user held on past payment
-- dates.

CREATE TABLE IF NOT EXISTS dividend_income (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id           UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  ticker            TEXT NOT NULL,
  pay_date          DATE NOT NULL,
  shares_at_payment NUMERIC NOT NULL,
  per_share_amount  NUMERIC NOT NULL,
  amount            NUMERIC NOT NULL,
  currency          TEXT NOT NULL DEFAULT 'USD',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, ticker, pay_date)
);

CREATE INDEX IF NOT EXISTS idx_dividend_income_user ON dividend_income (user_id);

ALTER TABLE dividend_income ENABLE ROW LEVEL SECURITY;

CREATE POLICY dividend_income_self ON dividend_income
  FOR ALL USING (user_id = auth.uid());


-- ===== 055_cash_holdings_cetes_rate.sql =====
-- Migration 055: rate tracking on cash holdings
--
-- CETES and US Treasury bonds lock in their yield at purchase (unlike a
-- savings account, the rate doesn't float day to day) — so when a "cetes" or
-- "bonds" cash holding is created, the backend captures a live rate
-- (Banxico's 364-day CETES rate, SIE series SF43945, or FRED's 1-year
-- Treasury constant-maturity rate, series DGS1) and the capture timestamp.
-- A user can also type their own annual rate manually (e.g. a bank
-- account's real APY) — a manual rate always wins over auto-fetching. The
-- displayed amount then accrues from whichever rate is set via simple
-- annualized interest, the same convention these yields are quoted in.

ALTER TABLE cash_holdings
  ADD COLUMN IF NOT EXISTS rate_pct NUMERIC,
  ADD COLUMN IF NOT EXISTS rate_captured_at TIMESTAMPTZ;


-- ===== 056_atomic_msg_count.sql =====
-- Chat's msg_count limit was enforced with a plain read-then-write from
-- Python (select msg_count, compare to limit, update msg_count + 1) — two
-- concurrent requests (double-submit, flaky-network retry) can both read the
-- same count, both pass the limit check, and both write the same N+1,
-- silently losing an increment. Repeated concurrent bursts let a user
-- exceed their daily message limit indefinitely, with no cap on the
-- resulting Anthropic API spend. This function does the read, window-reset,
-- limit-check and increment as a single atomic statement under a row lock,
-- so concurrent callers serialize instead of racing.
CREATE OR REPLACE FUNCTION increment_msg_count_if_allowed(
  p_user_id UUID,
  p_limit INT,
  p_window_hours INT
)
RETURNS TABLE(allowed BOOLEAN, new_count INT, window_start TIMESTAMPTZ)
LANGUAGE plpgsql
AS $$
DECLARE
  v_window_start TIMESTAMPTZ;
  v_count INT;
BEGIN
  SELECT msg_window_start, msg_count INTO v_window_start, v_count
  FROM user_profiles
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_window_start IS NULL OR NOW() - v_window_start >= make_interval(hours => p_window_hours) THEN
    UPDATE user_profiles
    SET msg_count = 1, msg_window_start = NOW()
    WHERE user_id = p_user_id
    RETURNING user_profiles.msg_window_start INTO v_window_start;

    RETURN QUERY SELECT TRUE, 1, v_window_start;
    RETURN;
  END IF;

  IF v_count >= p_limit THEN
    RETURN QUERY SELECT FALSE, v_count, v_window_start;
    RETURN;
  END IF;

  UPDATE user_profiles
  SET msg_count = msg_count + 1
  WHERE user_id = p_user_id
  RETURNING user_profiles.msg_count INTO v_count;

  RETURN QUERY SELECT TRUE, v_count, v_window_start;
END;
$$;


-- ===== 057_view_mode_default_advanced.sql =====
-- Diego wants the dense "Avanzado" stock table to be the default view for
-- EVERY user in Portfolio and Watchlist, never "Básico" — with FinancialTip
-- (i) icons doing the explaining for básico-level users instead of hiding
-- the real metrics behind a dumbed-down default.
--
-- Both columns were added with DEFAULT 'basic' (migrations 020/021), which
-- Postgres backfilled onto every existing row at the time — so today
-- 'basic' is indistinguishable between "a user deliberately chose básico"
-- and "this row was never touched." Per Diego's explicit "para todos,
-- siempre, nunca en básico," this resets everyone (not just future rows)
-- to 'advanced'. Anyone who genuinely prefers the simple card view can
-- still switch back with the toggle in the UI — nothing here removes that.

ALTER TABLE user_profiles ALTER COLUMN portfolio_view_mode SET DEFAULT 'advanced';
ALTER TABLE user_profiles ALTER COLUMN watchlist_view_mode SET DEFAULT 'advanced';

UPDATE user_profiles SET portfolio_view_mode = 'advanced' WHERE portfolio_view_mode = 'basic';
UPDATE user_profiles SET watchlist_view_mode = 'advanced' WHERE watchlist_view_mode = 'basic';


