-- ===== 059_chat_deleted_sessions.sql =====
-- Migration 059: Tombstone deleted chat sessions so they never resurrect.
-- Chat session deletion was a hard DELETE from chat_history with nothing
-- recorded to remember "this session_id must stay dead" — any later event
-- that could re-insert a row with that session_id (a queued /save-message
-- call that raced the delete, a cross-device sync poll, a stale locally
-- cached copy on another browser/device) silently resurrected the "deleted"
-- chat. This table is the tombstone: /save-message refuses to insert for a
-- tombstoned session_id, and /history returns the tombstoned ids so every
-- client prunes its own local cache to match.
CREATE TABLE IF NOT EXISTS chat_deleted_sessions (
    user_id    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    session_id TEXT NOT NULL,
    deleted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id, session_id)
);

ALTER TABLE chat_deleted_sessions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users own deleted chat sessions" ON chat_deleted_sessions FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Service: deleted chat sessions"  ON chat_deleted_sessions FOR ALL TO service_role USING (true);


-- ===== 060_research_knowledge_base.sql =====
-- ============================================================================
-- 060_research_knowledge_base.sql
--
-- Fase 3, Incremento 1 (see /Users/diegoarria/.claude/plans/stateful-painting-flurry.md):
-- the foundation of the Investment Research Engine — a permanent, per-COMPANY
-- (never per-user), incrementally-updated knowledge store. Confirmed gap in
-- the audit: every timeline/history-shaped table that existed before this
-- (fmg_events, investment_graph_events, investment_decisions) is scoped to
-- user_id — it tracks what a USER did/thought about a company, never the
-- company's own objective history. This table is deliberately the opposite
-- shape: shared, append-only, one row per new piece of real knowledge.
--
-- company_knowledge_snapshots: one row per (ticker, section) EACH TIME an
-- engine (Business Understanding, Competitive, Industry, Management,
-- Document Intelligence — Fase 3 Incrementos 2-5) produces a fresh read.
-- Never UPDATEd — Change Detection (Incremento 6) diffs row N against row
-- N-1 for the same (ticker, section), which requires the old row to still
-- exist. "Incremental" here means "a new row when there's new signal," not
-- "mutate the existing row in place."
--
-- company_timeline_events: the shared, per-company event history the
-- Timeline Engine (Incremento 6) reads and Change Detection writes to.
-- headline_hash dedup follows the exact same pattern as
-- major_news_events(event_date, headline_hash) from migration 036 — the
-- correct precedent for a shared (not per-user) table in this codebase.
--
-- Both tables: RLS enabled, service_role only, zero user-facing policies —
-- same model as major_news_events (036) and security_events (033). No
-- end-user ever reads these tables directly; the research/ package's own
-- service functions are the only callers.
-- ============================================================================

CREATE TABLE IF NOT EXISTS company_knowledge_snapshots (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ticker         TEXT NOT NULL,
  section        TEXT NOT NULL,   -- 'document_intel'|'business_understanding'|'competitive'|'industry'|'management'
  content        JSONB NOT NULL,  -- engine-specific shape; always includes a claims[] array (EvidenceTaggedClaim)
  source_period  TEXT,            -- e.g. 'FY2025', '2026-Q2' — which filing/earnings period this reflects
  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_knowledge_snapshots_lookup
  ON company_knowledge_snapshots (ticker, section, created_at DESC);

ALTER TABLE company_knowledge_snapshots ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: knowledge snapshots" ON company_knowledge_snapshots;
CREATE POLICY "Service: knowledge snapshots" ON company_knowledge_snapshots
  FOR ALL TO service_role USING (true) WITH CHECK (true);

CREATE TABLE IF NOT EXISTS company_timeline_events (
  id                        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ticker                    TEXT NOT NULL,
  event_date                DATE,             -- real event date if known; NULL if only approximately dated
  event_type                TEXT NOT NULL,    -- ceo_change|ma|spinoff|product_launch|new_segment|regulatory|guidance_change|margin_shift|strategy_change
  headline                  TEXT NOT NULL,
  detail                    JSONB,            -- claims[], magnitude if applicable (e.g. margin_shift: {from, to, pct})
  detected_from_snapshot_id UUID REFERENCES company_knowledge_snapshots(id),
  source_claim              JSONB,            -- the EvidenceTaggedClaim that originated this event
  headline_hash             TEXT NOT NULL,    -- md5(ticker+event_type+headline) — dedup, same pattern as major_news_events
  created_at                TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_timeline_dedup
  ON company_timeline_events (ticker, event_type, headline_hash);
CREATE INDEX IF NOT EXISTS idx_timeline_ticker_date
  ON company_timeline_events (ticker, event_date DESC NULLS LAST);

ALTER TABLE company_timeline_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: company timeline events" ON company_timeline_events;
CREATE POLICY "Service: company timeline events" ON company_timeline_events
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 061_research_thesis.sql =====
-- ============================================================================
-- 061_research_thesis.sql
--
-- Fase 3, Incremento 7 (see /Users/diegoarria/.claude/plans/stateful-painting-flurry.md):
-- the Thesis Engine (Parte F). The brief asks, simultaneously, for the
-- thesis to be "auto-constructed" by the AI AND to "never automatically
-- overwrite an existing thesis" AND to be "editable by the user" — three
-- requirements that can't coexist in one table. Resolved with two tables:
--
-- research_thesis_drafts: Nuvos's own OBJECTIVE research view — no owner,
-- regenerated in-place (UPSERT on ticker) whenever there's new material
-- Change Detection signal. This is what "auto-construida" refers to. RLS
-- modeled on major_news_events (migration 036) — service_role only, this
-- is never a user's personal data.
--
-- user_investment_theses: the user's PERSONAL, editable thesis. Only ever
-- created by explicit user action (writing one from scratch, or "forking"
-- a research_thesis_drafts snapshot as a starting point) or by the Thesis
-- Tracker (Incremento 8) creating a NEW version row — never UPDATEd by any
-- automated process. is_current marks the live version per (user_id,
-- ticker); parent_thesis_id chains versions so Thesis Tracker can compare
-- N vs N-1 the same way company_knowledge_snapshots does for research.
-- ============================================================================

CREATE TABLE IF NOT EXISTS research_thesis_drafts (
  id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ticker                TEXT NOT NULL UNIQUE,
  generated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  based_on_snapshot_id  UUID REFERENCES company_knowledge_snapshots(id),
  thesis_summary        TEXT NOT NULL,
  strengths             JSONB NOT NULL,   -- EvidenceTaggedClaim[]
  critical_variables    JSONB NOT NULL,   -- EvidenceTaggedClaim[] — what has to hold true
  key_risks             JSONB NOT NULL,   -- EvidenceTaggedClaim[]
  invalidation_events   JSONB NOT NULL,   -- EvidenceTaggedClaim[] — what would fully invalidate the thesis
  confidence            TEXT NOT NULL     -- low|medium|high, aggregate
);

ALTER TABLE research_thesis_drafts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: research thesis drafts" ON research_thesis_drafts;
CREATE POLICY "Service: research thesis drafts" ON research_thesis_drafts
  FOR ALL TO service_role USING (true) WITH CHECK (true);

CREATE TABLE IF NOT EXISTS user_investment_theses (
  id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id               UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  ticker                TEXT NOT NULL,
  version               INT NOT NULL DEFAULT 1,
  parent_thesis_id      UUID REFERENCES user_investment_theses(id),
  forked_from_draft_id  UUID REFERENCES research_thesis_drafts(id),
  thesis_summary        TEXT NOT NULL,
  strengths             JSONB NOT NULL,
  critical_variables    JSONB NOT NULL,
  key_risks             JSONB NOT NULL,
  invalidation_events   JSONB NOT NULL,
  is_current            BOOLEAN NOT NULL DEFAULT true,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  edited_at             TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_user_theses_current ON user_investment_theses (user_id, ticker) WHERE is_current;

ALTER TABLE user_investment_theses ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users manage own investment theses" ON user_investment_theses;
CREATE POLICY "Users manage own investment theses" ON user_investment_theses
  FOR ALL USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());


-- ===== 062_user_investment_theses_account_deletion.sql =====
-- Migration 062: add user_investment_theses to the atomic account-deletion
-- function (migrations 035/040/041/043) now that migration 061 introduced
-- the table. Keep this in sync with _USER_DATA_TABLES in
-- backend/app/api/routes/auth.py. research_thesis_drafts is intentionally
-- NOT added — it has no user_id column, it is shared Nuvos research state,
-- not personal data.

CREATE OR REPLACE FUNCTION delete_user_data(p_user_id UUID)
RETURNS VOID
LANGUAGE plpgsql
AS $$
DECLARE
  tbl TEXT;
  tables TEXT[] := ARRAY[
    'user_profiles', 'user_portfolio', 'portfolio_positions', 'user_paper_trading',
    'user_daily_usage', 'web_push_subscriptions', 'chat_history',
    'notifications', 'watchlist', 'notification_preferences',
    'notification_log', 'notification_analytics', 'investment_decisions',
    'support_tickets', 'user_feedback', 'price_alerts', 'pending_actions',
    'upsell_dismissals', 'upsell_events', 'brokerage_connections',
    'voice_call_transcripts', 'user_financial_goals', 'user_sector_preferences',
    'library_items', 'habit_engagement',
    'fmg_memories', 'fmg_behavioral_patterns', 'fmg_events',
    'fmg_portfolio_snapshots', 'fmg_annual_reports',
    'valuation_alert_state', 'thesis_drift_state',
    'clip_likes', 'clip_saves', 'clip_views', 'clip_comments',
    'research_jobs', 'research_reports', 'security_events',
    'investment_graph_events', 'user_investment_theses'
  ];
BEGIN
  FOREACH tbl IN ARRAY tables LOOP
    BEGIN
      EXECUTE format('DELETE FROM %I WHERE user_id::text = $1', tbl) USING p_user_id::text;
    EXCEPTION
      WHEN undefined_table OR undefined_column THEN
        RAISE WARNING 'delete_user_data: skipped % for % — table/column schema unexpected (%)', tbl, p_user_id, SQLERRM;
    END;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION delete_user_data(UUID) TO service_role;


-- ===== 063_research_hypothesis_outcomes.sql =====
-- ============================================================================
-- 063_research_hypothesis_outcomes.sql
--
-- Fase 3, Incremento 8 (see /Users/diegoarria/.claude/plans/stateful-painting-flurry.md):
-- schema for the Benchmark Engine (Parte N, Incremento 11) — built now,
-- populated by the Thesis Tracker (Parte H, this increment) as soon as
-- there's something real to track, per the plan: "Inserta filas
-- research_hypothesis_outcomes con outcome=NULL (pendiente de evaluación
-- futura) — schema listo desde ya aunque el motor de agregación (N)
-- llegue después." Building the aggregation engine before there's >=1
-- real quarter of tracked hypotheses would be pure scaffolding with zero
-- signal — the schema comes first, the engine comes last.
--
-- One row per individually-verifiable claim Nuvos or a user's thesis made
-- (a critical variable, a risk, an invalidation event, a catalyst) —
-- `outcome` starts NULL (a real prediction, not yet evaluable) and is
-- filled in later, by the Thesis Tracker's NEXT review, once real
-- evidence exists to judge it.
--
-- Shared/global — this measures the quality of NUVOS'S OWN research
-- across every user and ticker, not one user's personal accuracy, so
-- there is no user_id column and RLS is service_role-only, same model as
-- major_news_events (migration 036).
-- ============================================================================

CREATE TABLE IF NOT EXISTS research_hypothesis_outcomes (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ticker            TEXT NOT NULL,
  sector            TEXT,
  industry          TEXT,
  source_thesis_id  UUID REFERENCES research_thesis_drafts(id),
  claim_text        TEXT NOT NULL,
  claim_type        TEXT NOT NULL,   -- critical_variable|risk|invalidation_event|catalyst
  predicted_at      TIMESTAMPTZ NOT NULL,
  evaluated_at      TIMESTAMPTZ,
  outcome           TEXT,            -- confirmed|refuted|inconclusive|NULL (pending)
  evaluation_note   TEXT
);

CREATE INDEX IF NOT EXISTS idx_hypothesis_outcomes_ticker ON research_hypothesis_outcomes (ticker, predicted_at DESC);
CREATE INDEX IF NOT EXISTS idx_hypothesis_outcomes_pending ON research_hypothesis_outcomes (outcome) WHERE outcome IS NULL;

ALTER TABLE research_hypothesis_outcomes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: research hypothesis outcomes" ON research_hypothesis_outcomes;
CREATE POLICY "Service: research hypothesis outcomes" ON research_hypothesis_outcomes
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 064_detail_level.sql =====
-- Fase 4, Incremento 1 — "Nivel de Detalle" (Principiante/Intermedio/
-- Avanzado/Profesional), see /Users/diegoarria/.claude/plans/
-- stateful-painting-flurry.md. Deliberately a NEW, separate preference from
-- portfolio_view_mode/watchlist_view_mode (migrations 020/021/057) — those
-- are a binary basic/advanced density toggle per page; this is an explicit
-- 4-level "how much do I want to see right now" setting that will control
-- section visibility across the redesigned /subvaluadas dashboard.
--
-- Default 'intermedio' (not 'avanzado', unlike the 057 reset) — see the
-- plan's Decisión 2 for why: this setting hides/shows whole SECTIONS, not
-- just tooltips, so defaulting to the most complex view risks overwhelming
-- a new user, and defaulting to the simplest risks hiding real data from an
-- experienced one on day one. Intermedio is the safer starting point; users
-- can move either direction immediately.

ALTER TABLE user_profiles ADD COLUMN IF NOT EXISTS detail_level VARCHAR(20) DEFAULT 'intermedio';


-- ===== 065_investment_checklist.sql =====
-- ============================================================================
-- 065_investment_checklist.sql
--
-- Fase 4, Incremento 8 (Investment Checklist, Parte H — see
-- /Users/diegoarria/.claude/plans/stateful-painting-flurry.md): a
-- customizable checklist that must be completed before a user marks a
-- company as "Invertible." Minimal backend support per Decisión 3 — no new
-- financial/scoring logic, just persistence for a UI gate.
--
-- user_checklist_items: the user's PERSONALIZED item list. Empty (no rows)
-- for a user who has never customized it — the backend returns a real
-- default set (app/services/checklist_service.py's DEFAULT_CHECKLIST_ITEMS)
-- in that case, never fabricating rows just to have something to return.
-- The first add/remove action "materializes" the defaults into real rows
-- (see checklist_service.py) so personalization is additive, not a
-- from-scratch rebuild. `label IS NULL` means "use the i18n translation
-- for this default item_key" (frontend concern, matches the existing
-- subvaluadas.checklist.items.* convention); a real label means a
-- user-authored custom item.
--
-- checklist_completions: a row = this item is checked for this
-- (user, ticker) — deleting the row unchecks it. Same
-- "row-exists-is-the-state" pattern watchlist/price_alerts already use.
--
-- investable_marks: a row = the user has marked this ticker "Invertible."
-- Deliberately NOT a column on `watchlist` — marking a company investable
-- shouldn't require it to already be followed.
-- ============================================================================

CREATE TABLE IF NOT EXISTS user_checklist_items (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  item_key    TEXT NOT NULL,
  label       TEXT,
  sort_order  INT NOT NULL DEFAULT 0,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, item_key)
);

ALTER TABLE user_checklist_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users manage own checklist items" ON user_checklist_items;
CREATE POLICY "Users manage own checklist items" ON user_checklist_items
  FOR ALL USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

CREATE TABLE IF NOT EXISTS checklist_completions (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  ticker      TEXT NOT NULL,
  item_key    TEXT NOT NULL,
  checked_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, ticker, item_key)
);

CREATE INDEX IF NOT EXISTS idx_checklist_completions_lookup ON checklist_completions (user_id, ticker);

ALTER TABLE checklist_completions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users manage own checklist completions" ON checklist_completions;
CREATE POLICY "Users manage own checklist completions" ON checklist_completions
  FOR ALL USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

CREATE TABLE IF NOT EXISTS investable_marks (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  ticker      TEXT NOT NULL,
  marked_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, ticker)
);

ALTER TABLE investable_marks ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users manage own investable marks" ON investable_marks;
CREATE POLICY "Users manage own investable marks" ON investable_marks
  FOR ALL USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());


-- ===== 066_checklist_account_deletion.sql =====
-- Migration 066: add the three new Fase 4 Incremento 8 tables to the atomic
-- account-deletion function (migrations 035/040/041/043/062) now that
-- migration 065 introduced them. Keep this in sync with _USER_DATA_TABLES
-- in backend/app/api/routes/auth.py.

CREATE OR REPLACE FUNCTION delete_user_data(p_user_id UUID)
RETURNS VOID
LANGUAGE plpgsql
AS $$
DECLARE
  tbl TEXT;
  tables TEXT[] := ARRAY[
    'user_profiles', 'user_portfolio', 'portfolio_positions', 'user_paper_trading',
    'user_daily_usage', 'web_push_subscriptions', 'chat_history',
    'notifications', 'watchlist', 'notification_preferences',
    'notification_log', 'notification_analytics', 'investment_decisions',
    'support_tickets', 'user_feedback', 'price_alerts', 'pending_actions',
    'upsell_dismissals', 'upsell_events', 'brokerage_connections',
    'voice_call_transcripts', 'user_financial_goals', 'user_sector_preferences',
    'library_items', 'habit_engagement',
    'fmg_memories', 'fmg_behavioral_patterns', 'fmg_events',
    'fmg_portfolio_snapshots', 'fmg_annual_reports',
    'valuation_alert_state', 'thesis_drift_state',
    'clip_likes', 'clip_saves', 'clip_views', 'clip_comments',
    'research_jobs', 'research_reports', 'security_events',
    'investment_graph_events', 'user_investment_theses',
    'user_checklist_items', 'checklist_completions', 'investable_marks'
  ];
BEGIN
  FOREACH tbl IN ARRAY tables LOOP
    BEGIN
      EXECUTE format('DELETE FROM %I WHERE user_id::text = $1', tbl) USING p_user_id::text;
    EXCEPTION
      WHEN undefined_table OR undefined_column THEN
        RAISE WARNING 'delete_user_data: skipped % for % — table/column schema unexpected (%)', tbl, p_user_id, SQLERRM;
    END;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION delete_user_data(UUID) TO service_role;


-- ===== 067_smart_alerts.sql =====
-- ============================================================================
-- 067_smart_alerts.sql
--
-- Fase 4, Incremento 10 (Alertas Inteligentes, Parte J — see
-- /Users/diegoarria/.claude/plans/stateful-painting-flurry.md): bridges
-- signals Fase 2/3 ALREADY compute into push notifications. No new
-- detection logic — only 5 toggles, each backed by a real existing signal
-- (see app/services/smart_alerts_service.py's module docstring for exactly
-- which engine output backs each category). Deliberately excludes "moat
-- change"/"capital allocation change" from the original 8-category brief —
-- neither has a real detected-change signal anywhere in the codebase today,
-- and inventing one would violate this phase's own rule against new
-- financial/detection logic (confirmed with the user before building this).
--
-- smart_alert_state: one row per (user, ticker, category) — the LAST real
-- value seen for that category on that ticker, so the daily job can detect
-- a genuine transition instead of re-notifying the same state every day.
-- Same "store last-seen state, compare, notify on change" pattern as
-- saved_valuations.notified_milestones (Incremento 9's sibling job),
-- generalized into its own table since (unlike saved valuations) there's
-- no natural per-user row to attach this state to for arbitrary watchlist
-- tickers.
-- ============================================================================

CREATE TABLE IF NOT EXISTS smart_alert_state (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  ticker      TEXT NOT NULL,
  category    TEXT NOT NULL,  -- 'thesis_change' | 'guidance_change' | 'roic_fcf_deterioration' | 'new_risk' | 'price_in_range'
  last_value  TEXT,           -- last real value seen (event id, direction, risk-list hash, 'in_range'/'out_of_range')
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, ticker, category)
);

CREATE INDEX IF NOT EXISTS idx_smart_alert_state_lookup ON smart_alert_state (user_id, ticker);

ALTER TABLE smart_alert_state ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users manage own smart alert state" ON smart_alert_state;
CREATE POLICY "Users manage own smart alert state" ON smart_alert_state
  FOR ALL USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

-- 5 new push toggles, same DEFAULT true convention as every existing
-- push_* column in this table (migration 011).
ALTER TABLE notification_preferences ADD COLUMN IF NOT EXISTS push_thesis_changes         BOOLEAN DEFAULT true;
ALTER TABLE notification_preferences ADD COLUMN IF NOT EXISTS push_guidance_changes        BOOLEAN DEFAULT true;
ALTER TABLE notification_preferences ADD COLUMN IF NOT EXISTS push_roic_fcf_deterioration  BOOLEAN DEFAULT true;
ALTER TABLE notification_preferences ADD COLUMN IF NOT EXISTS push_new_risks               BOOLEAN DEFAULT true;
ALTER TABLE notification_preferences ADD COLUMN IF NOT EXISTS push_price_in_range          BOOLEAN DEFAULT true;


