-- ===== 071_belvo_connections.sql =====
-- Migration 071: Belvo support on brokerage_connections
--
-- Belvo (LatAm open banking — bank accounts + brokerage aggregation,
-- starting with Mexico) becomes provider #3 on the existing
-- brokerage_connections table (Plaid, IOL, now Belvo), see
-- backend/app/api/routes/brokerage.py and backend/app/api/routes/belvo.py.
--
-- Unlike Plaid/IOL, Belvo doesn't hand the backend a per-link bearer
-- token — the backend authenticates to Belvo server-to-server via
-- secret_id/secret_password (config.py) for every call, and the link
-- itself is identified by Belvo's own belvo_link_id. access_token's
-- NOT NULL is dropped so Belvo rows can leave it null rather than
-- storing a fake placeholder value.

ALTER TABLE brokerage_connections
  ADD COLUMN IF NOT EXISTS belvo_link_id TEXT,
  ADD COLUMN IF NOT EXISTS belvo_category TEXT,          -- 'banking' | 'investment' — Belvo's own distinction
  ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'valid',  -- 'valid' | 'token_required' | 'login_error' | 'unlinked'
  ADD COLUMN IF NOT EXISTS status_updated_at TIMESTAMPTZ;

ALTER TABLE brokerage_connections
  ALTER COLUMN access_token DROP NOT NULL;

CREATE INDEX IF NOT EXISTS idx_brokerage_connections_belvo_link_id
  ON brokerage_connections (belvo_link_id)
  WHERE belvo_link_id IS NOT NULL;


-- ===== 072_belvo_cash_source.sql =====
-- Migration 072: Belvo-sourced cash holdings
--
-- cash_holdings is one row per holding (not an overwrite-the-whole-array
-- blob like user_portfolio), so a Belvo sync job can safely upsert on
-- (user_id, belvo_account_id) and only ever touch its own rows — manual
-- rows (belvo_account_id IS NULL) are never affected. See
-- backend/app/api/routes/belvo.py and the plan at
-- /Users/diegoarria/.claude/plans/cosmic-munching-crown.md, section 1.
--
-- cash_holdings.user_id already has ON DELETE CASCADE to auth.users
-- (migration 053), so Belvo-sourced rows are cleaned up on account
-- deletion with no further changes needed.

ALTER TABLE cash_holdings
  ADD COLUMN IF NOT EXISTS source TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'belvo')),
  ADD COLUMN IF NOT EXISTS belvo_connection_id UUID REFERENCES brokerage_connections(id) ON DELETE CASCADE,
  ADD COLUMN IF NOT EXISTS belvo_account_id TEXT;

CREATE UNIQUE INDEX IF NOT EXISTS cash_holdings_belvo_account_uidx
  ON cash_holdings (user_id, belvo_account_id)
  WHERE belvo_account_id IS NOT NULL;


-- ===== 073_backfill_trial_started_at.sql =====
-- ============================================================================
-- 073_backfill_trial_started_at.sql
--
-- Data backfill, not a schema change. Fixes existing users whose
-- trial_started_at was never set (a bug in earlier account-creation paths,
-- fixed in code separately — see profile.py's create_profile, which now
-- guarantees trial_started_at for every new/updated profile) — those users
-- currently show as "free" in is_premium_active() (backend/app/core/
-- subscription.py) even though they should be within (or should have
-- started) their 30-day trial.
--
-- Diego's explicit decision (2026-08-12): backfill using each user's REAL
-- signup date (created_at), not a fresh 30 days from today — matches his
-- own framing ("desde la fecha en que se crean su cuenta"). A user who
-- signed up more than 30 days ago and never had trial_started_at set will
-- correctly land as an expired trial (free) under this backfill — that is
-- the intended, chosen behavior, not a bug.
--
-- Never touches paid subscribers (subscription_tier premium/pro) or anyone
-- who already has a trial_started_at — this only fills in the genuinely
-- missing case.
-- ============================================================================

UPDATE user_profiles
SET trial_started_at = created_at
WHERE trial_started_at IS NULL
  AND subscription_tier NOT IN ('premium', 'pro')
  AND created_at IS NOT NULL;


-- ===== 074_macro_economic_events.sql =====
-- ============================================================================
-- 074_macro_economic_events.sql
--
-- Backs the Watchlist calendar's new macro-economic-events layer (FOMC, CPI,
-- NFP, GDP, PMIs, jobless claims, etc.), on top of the existing per-ticker
-- earnings/dividend events already shown there. Populated by a daily cron
-- (worker.py's job_refresh_macro_calendar) from FMP's economic-calendar API,
-- never written to directly by any request path — mirrors major_news_events'
-- (036) service-role-only shape, since nothing in this codebase lets the
-- frontend talk to Supabase directly; it always reads through a backend API
-- route instead.
--
-- event_id is a stable dedup key (sha1 of event_type|event_name|event_date_utc)
-- so re-running the daily sync never creates duplicate rows across syncs,
-- name changes, or repeated cron runs — enforced by the UNIQUE constraint,
-- with the sync using upsert(on_conflict="event_id").
-- ============================================================================

CREATE TABLE IF NOT EXISTS macro_economic_events (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id       TEXT NOT NULL UNIQUE,        -- sha1(event_type|event_name|event_date_utc)
  event_type     TEXT NOT NULL,               -- canonical Nuvos type, e.g. 'cpi', 'fomc_rate_decision'
  event_name     TEXT NOT NULL,               -- source's raw label, verbatim (e.g. "Core Inflation Rate YoY (Sep)")
  event_date_utc TIMESTAMPTZ NOT NULL,
  country        TEXT NOT NULL DEFAULT 'US',
  impact_source  TEXT,                        -- source's own raw impact rating, kept for reference/audit
  impact_level   TEXT NOT NULL,               -- Nuvos's fixed classification: VERY_HIGH | HIGH | MEDIUM
  actual_value   TEXT,
  estimate_value TEXT,
  previous_value TEXT,
  unit           TEXT,
  speaker_name   TEXT,                        -- only for fed_speaker events, extracted from the source's own event name
  source         TEXT NOT NULL DEFAULT 'fmp',
  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_macro_economic_events_date ON macro_economic_events(event_date_utc);
CREATE INDEX IF NOT EXISTS idx_macro_economic_events_type_date ON macro_economic_events(event_type, event_date_utc);

-- Internal/system table — no end-user ever reads it directly. Only the
-- backend's service_role writes or reads it; frontend reads through the
-- GET /api/watchlist/macro-calendar route (mirrors major_news_events' 036
-- pattern and every other backend-owned table in this codebase).
ALTER TABLE macro_economic_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: macro economic events" ON macro_economic_events;
CREATE POLICY "Service: macro economic events" ON macro_economic_events
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 075_decision_quiz_answers.sql =====
-- Migration 075: structured Q&A answers on the investment decisions diary
-- Run in Supabase SQL Editor
--
-- Backs the optional "self-check" mini-quiz on the Oportunidades screen
-- (CompanyDiagnosticCard / mobile subvaluadas) — 5 free-text questions
-- about a company ("¿Cómo gana dinero?", etc.) the user can answer before
-- deciding, saved to their existing Diario de Decisiones so they can
-- revisit them later. `investment_decisions.notes` (migration 007) is a
-- single TEXT field — squashing 5 Q&A pairs into it would lose structure
-- (no per-question display/edit later), so this adds a real JSONB column
-- instead: [{"question": "...", "answer": "..."}, ...].

ALTER TABLE investment_decisions
  ADD COLUMN IF NOT EXISTS quiz_answers JSONB;


-- ===== 076_rls_daily_questions.sql =====
-- ============================================================================
-- 076_rls_daily_questions.sql
--
-- Security audit finding: daily_questions and daily_question_of_the_day
-- (070_weekly_rituals.sql) were the only two remaining user-facing tables
-- with RLS never enabled at all — not "enabled with zero policies" like
-- benchmark_cohort_stats (032_rls_hardening.sql), but genuinely off. Both
-- are global curated/scheduling content (no user_id column, not per-user
-- data) that's always read through the backend's own API (service_role,
-- bypasses RLS) — no legitimate client-side Supabase call ever needs to
-- touch either table directly. Without RLS, the public anon key (which is
-- intentionally exposed client-side — see frontend/web/src/lib/supabase.ts)
-- could otherwise INSERT/UPDATE/DELETE the curated question bank or which
-- question is "live" today directly against Supabase's REST API.
--
-- Same defense-in-depth reasoning as 032_rls_hardening.sql's own governing
-- principle: never rely on an unverified role attribute (assuming
-- service_role has BYPASSRLS) — make the intended access explicit.
-- ============================================================================

ALTER TABLE daily_questions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: daily questions" ON daily_questions;
CREATE POLICY "Service: daily questions" ON daily_questions
  FOR ALL TO service_role USING (true) WITH CHECK (true);

ALTER TABLE daily_question_of_the_day ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: daily question of the day" ON daily_question_of_the_day;
CREATE POLICY "Service: daily question of the day" ON daily_question_of_the_day
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 077_wrapped_longest_streak.sql =====
-- ============================================================================
-- 077_wrapped_longest_streak.sql
--
-- Nuvos Wrapped's "racha más larga" screen needs a historical maximum, but
-- user_profiles.streak_count is overwritten every day (current streak
-- only) — there's no daily-activity log to reconstruct past streaks from,
-- so history before this migration is genuinely unrecoverable. New column
-- starts at today's current streak as a floor, then app/api/routes/learn.py
-- keeps it as a running max going forward.
-- ============================================================================

ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS longest_streak_count integer NOT NULL DEFAULT 0;

UPDATE user_profiles
  SET longest_streak_count = COALESCE(streak_count, 0)
  WHERE longest_streak_count < COALESCE(streak_count, 0);


-- ===== 078_margin_of_safety_alerts.sql =====
-- ============================================================================
-- 078_margin_of_safety_alerts.sql
--
-- Revives saved_valuations (migration 048) for the current Nuvos AI Fair
-- Value Engine instead of the retired manual-DCF-sliders methodology.
-- growth_pct/discount_rate_pct/terminal_growth_pct become nullable (the
-- new save flow never fills them — no manual DCF sliders exist on
-- /subvaluadas anymore, see valuationPanelMode.ts). target_margin_of_
-- safety_pct is the user's own configured alert threshold, replacing the
-- old fixed 6-value milestone ladder. notified_at replaces the
-- notified_milestones ratchet — a single one-shot threshold only ever
-- needs one timestamp, null until it fires, reset to null when the user
-- edits/re-saves their threshold (same "re-saving is a new baseline"
-- rule the old ratchet already followed).
-- ============================================================================

ALTER TABLE saved_valuations
  ALTER COLUMN growth_pct DROP NOT NULL,
  ALTER COLUMN discount_rate_pct DROP NOT NULL,
  ALTER COLUMN terminal_growth_pct DROP NOT NULL;

ALTER TABLE saved_valuations
  ADD COLUMN IF NOT EXISTS target_margin_of_safety_pct NUMERIC,
  ADD COLUMN IF NOT EXISTS notified_at TIMESTAMPTZ;


-- ===== 079_manual_premium_grants.sql =====
-- ============================================================================
-- 079_manual_premium_grants.sql
--
-- Grants permanent premium to a small, explicit list of users (Diego,
-- 2026-08-20) — not a paid Stripe subscription, not a trial, not the
-- time-limited streak/referral bonus (streak_bonus_premium_until).
--
-- subscription_tier = 'premium' alone is already permanent: is_premium_active()
-- (backend/app/core/subscription.py) treats tier premium/pro as always-on,
-- with no linked expiry column, and Stripe's webhooks are the only thing
-- that ever sets it back to 'free' (backend/app/api/routes/billing.py).
-- These users have no stripe_customer_id, so no webhook will ever touch
-- their tier — this grant is durable by construction.
--
-- Adds subscription_source so a manually comp'd user can be told apart
-- from a real Stripe subscriber later (billing/reporting, admin views) —
-- no such column existed before this migration; every existing premium/pro
-- row predates it and is left NULL rather than guessed at, since we can't
-- retroactively know which of those were Stripe vs. some other manual
-- grant made before this column existed.
-- ============================================================================

ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS subscription_source text,
  ADD COLUMN IF NOT EXISTS premium_granted_at timestamptz;

UPDATE user_profiles
SET subscription_tier     = 'premium',
    subscription_source   = 'manual_comp',
    premium_granted_at    = now()
WHERE user_id IN (
  SELECT id FROM auth.users
  WHERE email IN (
    'diego.arria19@gmail.com',
    'melissa.arria@911-pymes.com',
    'rarria13@gmail.com'
  )
);


