-- repurposing into a configurable margin-of-safety threshold (migration
-- 078); neither survives in the app anymore, so the table goes too.

DROP TABLE IF EXISTS saved_valuations;


-- ===== 084_real_patrimonio_ath.sql =====
-- ============================================================================
-- 084_real_patrimonio_ath.sql
--
-- "Nuevo máximo histórico" milestone (investor_progress_service.py's
-- _check_new_ath) only ever compares fmg_portfolio_snapshots.total_value —
-- cost basis of stock positions ONLY, never live-priced, never including
-- cash available to invest or dividends received (the exact same gap
-- _real_portfolio_total was built to fix for Home/Wrapped/Morning Brief,
-- 2026-08-30 audit). Diego wants a real all-time-high push based on the
-- TRUE total: live position value + real cash + real dividends.
--
-- That real total was never recorded per historical day (cash/dividend
-- totals aren't snapshotted daily anywhere), so there's no history to
-- retroactively compute a max from — this column is a simple running max,
-- updated the moment a higher real total is observed, seeded silently on
-- first read (never fires a push comparing against a number that was never
-- real to begin with).
-- ============================================================================

ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS max_real_patrimonio_usd numeric;


-- ===== 085_duo_invite_consent.sql =====
-- Migration 085: Duo Plan invite consent
--
-- Security audit, Sep 2026: duo-setup used to immediately grant the
-- secondary account premium AND link them into a pairing that exposes
-- their investing-progress data to the primary (GET /duo-partner) — with
-- no consent step from the secondary at all. This adds a pending/accepted
-- state so the secondary must explicitly accept before anything is
-- granted or shared.
--
-- duo_invite_status lives on the PRIMARY's row (same place
-- duo_secondary_email/duo_secondary_user_id already live):
--   NULL      — no active invite
--   'pending' — primary invited, secondary hasn't responded yet
--   'accepted'— secondary accepted; premium granted, pairing visible both ways
--
-- No 'declined' state is stored — a decline just resets duo_secondary_email/
-- duo_secondary_user_id/duo_invite_status back to NULL so the primary can
-- invite someone else, same as when Stripe cancels/reassigns a pairing.

ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS duo_invite_status TEXT DEFAULT NULL
    CHECK (duo_invite_status IS NULL OR duo_invite_status IN ('pending', 'accepted'));


-- ===== 086_worker_heartbeat.sql =====
-- ============================================================================
-- 086_worker_heartbeat.sql
--
-- Single-row liveness marker for the worker.py APScheduler process. Written
-- every 60s by job_heartbeat (worker.py) — the standalone Nuvos Sentinel
-- monitor polls it via GET /sentinel/worker-heartbeat to tell "the whole
-- Railway worker process is stuck/crashed" apart from "the web process is
-- down" (health.py) — two different incidents needing different responses.
-- ============================================================================

CREATE TABLE IF NOT EXISTS worker_heartbeats (
  id           TEXT PRIMARY KEY,   -- e.g. 'apscheduler'
  last_beat_at TIMESTAMPTZ NOT NULL,
  detail       TEXT
);

-- Internal/admin-only, same pattern as security_events (033): no end-user
-- ever reads this, only the backend's service_role writes/reads it.
ALTER TABLE worker_heartbeats ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: worker heartbeats" ON worker_heartbeats;
CREATE POLICY "Service: worker heartbeats" ON worker_heartbeats
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 087_client_errors.sql =====
-- ============================================================================
-- 087_client_errors.sql
--
-- Frontend crash reports (React error boundary / Next.js global-error.tsx),
-- POSTed to /telemetry/client-error with no auth (the user may be logged
-- out or mid-crash when it fires). Read by GET /sentinel/client-errors so
-- the standalone Nuvos Sentinel monitor can flag a spike in full-screen
-- ("pantalla en blanco") frontend crashes.
-- ============================================================================

CREATE TABLE IF NOT EXISTS client_errors (
  id          BIGSERIAL PRIMARY KEY,
  message     TEXT,
  stack       TEXT,
  url         TEXT,
  user_agent  TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_client_errors_created_at ON client_errors(created_at DESC);

-- Internal/admin-only, same pattern as security_events (033).
ALTER TABLE client_errors ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: client errors" ON client_errors;
CREATE POLICY "Service: client errors" ON client_errors
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 088_ip_intel.sql =====
-- ============================================================================
-- 088_ip_intel.sql
--
-- Two additions for attack attribution in the standalone Nuvos Sentinel
-- monitor's technical panel:
--
-- 1. security_events (033) gains user_agent/accept_language — cheap, no
--    external API, written on every event by log_security_event().
-- 2. ip_intel_cache — geolocation/ISP/VPN/fraud data from IPQualityScore,
--    fetched LAZILY (only for IPs already involved in a flagged incident,
--    see app/services/ip_intel_service.py) and cached here so the same IP
--    is never looked up twice within its TTL — keeps this off the hot path
--    and off the free-tier quota during an actual attack burst.
-- ============================================================================

ALTER TABLE security_events ADD COLUMN IF NOT EXISTS user_agent TEXT;
ALTER TABLE security_events ADD COLUMN IF NOT EXISTS accept_language TEXT;

CREATE TABLE IF NOT EXISTS ip_intel_cache (
  ip_address    TEXT PRIMARY KEY,
  country       TEXT,
  region        TEXT,        -- state/province ("estado"/"región")
  city          TEXT,
  postal_code   TEXT,
  isp           TEXT,        -- "empresa que genera la conexión"
  organization  TEXT,
  asn           TEXT,
  connection_type TEXT,      -- 'Data Center' | 'Residential' | 'Mobile' | ... (IPQualityScore field)
  is_vpn        BOOLEAN,
  is_tor        BOOLEAN,
  is_proxy      BOOLEAN,
  fraud_score   INTEGER,     -- 0-100, IPQualityScore's own risk score
  raw           JSONB,       -- full provider response, for anything not modeled above
  fetched_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Internal/admin-only, same pattern as security_events (033).
ALTER TABLE ip_intel_cache ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: ip intel cache" ON ip_intel_cache;
CREATE POLICY "Service: ip intel cache" ON ip_intel_cache
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 089_backup_heartbeat.sql =====
-- ============================================================================
-- 089_backup_heartbeat.sql
--
-- Single-row liveness marker for the nightly Supabase backup
-- (.github/workflows/db-backup.yml) — written directly by that workflow via
-- psql immediately after a successful pg_dump, so a silently failing (or
-- silently not-running) backup finally has a queryable trail instead of
-- only a GitHub Actions red X nobody actively watches. Polled by
-- GET /sentinel/backup-heartbeat for the standalone Nuvos Sentinel monitor.
-- ============================================================================

CREATE TABLE IF NOT EXISTS backup_heartbeats (
  id              TEXT PRIMARY KEY,   -- 'nightly_backup'
  last_success_at TIMESTAMPTZ NOT NULL,
  detail          TEXT
);

-- Internal/admin-only, same pattern as security_events (033).
ALTER TABLE backup_heartbeats ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: backup heartbeats" ON backup_heartbeats;
CREATE POLICY "Service: backup heartbeats" ON backup_heartbeats
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 090_system_settings.sql =====
-- ============================================================================
-- 090_system_settings.sql
--
-- Tiny durable key-value store for system-wide toggles — first use: the
-- "AI kill switch" Diego controls from the standalone Nuvos Sentinel panel
-- (GET/POST /sentinel/ai-status, /sentinel/ai-toggle) to pause Arthur/every
-- AI feature during a suspected attack, planned maintenance, or any other
-- reason, without a deploy. See app/core/feature_flags.py.
-- ============================================================================

CREATE TABLE IF NOT EXISTS system_settings (
  key         TEXT PRIMARY KEY,
  value       JSONB NOT NULL,
  reason      TEXT,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_by  TEXT
);

INSERT INTO system_settings (key, value)
VALUES ('ai_enabled', 'true'::jsonb)
ON CONFLICT (key) DO NOTHING;

-- Internal/admin-only, same pattern as security_events (033).
ALTER TABLE system_settings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: system settings" ON system_settings;
CREATE POLICY "Service: system settings" ON system_settings
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 091_monthly_report.sql =====
-- ============================================================================
-- 091_monthly_report.sql
--
-- Nuvos Monthly Report — the monthly, Spotify-Wrapped-style personal report
-- (see app/services/monthly_report_service.py). Deliberately does NOT add a
-- monthly-snapshot/aggregate table: the report is computed live from data
-- that already exists (positions, investment_graph_events, fmg_portfolio_
-- snapshots, investor_progress_service) and cached in Redis (see cache.py),
-- same "compute live + cache" pattern Wrapped (the annual equivalent)
-- already uses — a second persisted-snapshot system would just duplicate
-- that.
--
-- The one thing that DOES need real persistence is which achievements a user
-- has already unlocked — unlike the report's numbers (recomputable from
-- source data any time), "you unlocked ANALISTA on 2026-09-03" is itself a
-- fact that must survive a cache eviction/TTL and be checked for
-- idempotency (an achievement unlocks exactly once, ever, never re-fires
-- next month).
-- ============================================================================

CREATE TABLE IF NOT EXISTS monthly_report_achievements (
  user_id        UUID NOT NULL,
  achievement_id TEXT NOT NULL,
  unlocked_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  -- Which report month first surfaced it — display-only ("desbloqueaste
  -- esto en septiembre"), never re-derived to decide idempotency (the PK does).
  report_year    INT NOT NULL,
  report_month   INT NOT NULL CHECK (report_month BETWEEN 1 AND 12),
  PRIMARY KEY (user_id, achievement_id)
);

CREATE INDEX IF NOT EXISTS idx_monthly_report_achievements_user
  ON monthly_report_achievements (user_id);

-- Same RLS shape as every other service-role-only table (see 090).
ALTER TABLE monthly_report_achievements ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: monthly report achievements" ON monthly_report_achievements;
CREATE POLICY "Service: monthly report achievements" ON monthly_report_achievements
  FOR ALL TO service_role USING (true) WITH CHECK (true);


