-- ===== 094_weekly_opportunities_history.sql =====
-- ============================================================================
-- 094_weekly_opportunities_history.sql
--
-- Diego, 2026-09-09 — the new Sunday 12:10pm ET "5 Nuevas Oportunidades de
-- Inversión" push (Premium only, worker.py's job_weekly_opportunities_push)
-- must NEVER repeat a ticker to the same user, ever — not just within a
-- rolling few-week window like the existing Screener Semanal history
-- (_weekly_history_key, a Redis cache entry with a TTL). A cache-based
-- "never repeat" isn't real — an eviction or TTL expiry silently forgets
-- history and the guarantee breaks. This is a real, permanent, durable
-- record instead: every ticker ever sent to a user via this specific push,
-- checked and appended to on every run, never expired.
-- ============================================================================

-- Dedicated opt-out toggle for the new push, same per-category-toggle
-- convention as every other notification_preferences column (067/093).
ALTER TABLE notification_preferences ADD COLUMN IF NOT EXISTS push_weekly_opportunities BOOLEAN DEFAULT true;

CREATE TABLE IF NOT EXISTS weekly_opportunities_history (
  user_id  UUID NOT NULL,
  ticker   TEXT NOT NULL,
  sent_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, ticker)
);

CREATE INDEX IF NOT EXISTS idx_weekly_opportunities_history_user
  ON weekly_opportunities_history (user_id);

-- Same RLS shape as every other service-role-only table (see 090/091).
ALTER TABLE weekly_opportunities_history ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: weekly opportunities history" ON weekly_opportunities_history;
CREATE POLICY "Service: weekly opportunities history" ON weekly_opportunities_history
  FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Add to the atomic account-deletion function (keep in sync with
-- _USER_DATA_TABLES in backend/app/api/routes/auth.py) — same pattern as
-- migration 082.
CREATE OR REPLACE FUNCTION delete_user_data(p_user_id UUID)
RETURNS VOID
LANGUAGE plpgsql
AS $$
DECLARE
  tbl TEXT;
  tables TEXT[] := ARRAY[
    'user_profiles', 'user_portfolio', 'portfolio_positions', 'user_paper_trading',
    'user_daily_usage', 'web_push_subscriptions', 'chat_history',
    'notifications', 'watchlist', 'notification_preferences',
    'notification_log', 'notification_analytics', 'investment_decisions',
    'support_tickets', 'user_feedback', 'price_alerts', 'pending_actions',
    'upsell_dismissals', 'upsell_events', 'brokerage_connections',
    'voice_call_transcripts', 'user_financial_goals', 'user_sector_preferences',
    'library_items', 'habit_engagement',
    'fmg_memories', 'fmg_behavioral_patterns', 'fmg_events',
    'fmg_portfolio_snapshots', 'fmg_annual_reports',
    'valuation_alert_state', 'thesis_drift_state',
    'clip_likes', 'clip_saves', 'clip_views', 'clip_comments',
    'research_jobs', 'research_reports', 'security_events',
    'investment_graph_events', 'user_investment_theses',
    'user_checklist_items', 'checklist_completions', 'investable_marks',
    'smart_alert_state', 'weekly_range_snapshots', 'weekly_opportunities_history'
  ];
BEGIN
  FOREACH tbl IN ARRAY tables LOOP
    BEGIN
      EXECUTE format('DELETE FROM %I WHERE user_id::text = $1', tbl) USING p_user_id::text;
    EXCEPTION
      WHEN undefined_table OR undefined_column THEN
        RAISE WARNING 'delete_user_data: skipped % for % — table/column schema unexpected (%)', tbl, p_user_id, SQLERRM;
    END;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION delete_user_data(UUID) TO service_role;


-- ===== 095_feature_notify_optins.sql =====
-- ============================================================================
-- 095_feature_notify_optins.sql
--
-- Diego, 2026-09-09 — clicking the Annual ScoreBoard (Nuvos Wrapped) card
-- outside its Dec 15–Jan 15 window (app/core/wrapped_window.py) now shows a
-- flashcard instead of navigating through to a locked page, with a "recibir
-- notificación" button. This is a generic, reusable one-time opt-in table
-- (not a notification_preferences column) since it's a single-fire signal
-- tied to a feature becoming available, not a recurring weekly/monthly
-- ritual toggle — `feature_key` lets other "coming soon" gates reuse this
-- same table later instead of each needing its own migration.
-- ============================================================================

CREATE TABLE IF NOT EXISTS feature_notify_optins (
  user_id      UUID NOT NULL,
  feature_key  TEXT NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  -- Set once the feature-availability push has actually been sent for this
  -- opt-in's current cycle (e.g. this year's Dec 15 open) — lets a recurring
  -- gate like Wrapped notify the same opted-in user again next year without
  -- a new row, by comparing this against the current cycle instead of
  -- deleting/recreating rows.
  notified_at  TIMESTAMPTZ,
  PRIMARY KEY (user_id, feature_key)
);

CREATE INDEX IF NOT EXISTS idx_feature_notify_optins_feature
  ON feature_notify_optins (feature_key);

-- Same RLS shape as every other service-role-only table (see 090/091/094).
ALTER TABLE feature_notify_optins ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: feature notify optins" ON feature_notify_optins;
CREATE POLICY "Service: feature notify optins" ON feature_notify_optins
  FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Add to the atomic account-deletion function (keep in sync with
-- _USER_DATA_TABLES in backend/app/api/routes/auth.py) — same pattern as
-- migration 094.
CREATE OR REPLACE FUNCTION delete_user_data(p_user_id UUID)
RETURNS VOID
LANGUAGE plpgsql
AS $$
DECLARE
  tbl TEXT;
  tables TEXT[] := ARRAY[
    'user_profiles', 'user_portfolio', 'portfolio_positions', 'user_paper_trading',
    'user_daily_usage', 'web_push_subscriptions', 'chat_history',
    'notifications', 'watchlist', 'notification_preferences',
    'notification_log', 'notification_analytics', 'investment_decisions',
    'support_tickets', 'user_feedback', 'price_alerts', 'pending_actions',
    'upsell_dismissals', 'upsell_events', 'brokerage_connections',
    'voice_call_transcripts', 'user_financial_goals', 'user_sector_preferences',
    'library_items', 'habit_engagement',
    'fmg_memories', 'fmg_behavioral_patterns', 'fmg_events',
    'fmg_portfolio_snapshots', 'fmg_annual_reports',
    'valuation_alert_state', 'thesis_drift_state',
    'clip_likes', 'clip_saves', 'clip_views', 'clip_comments',
    'research_jobs', 'research_reports', 'security_events',
    'investment_graph_events', 'user_investment_theses',
    'user_checklist_items', 'checklist_completions', 'investable_marks',
    'smart_alert_state', 'weekly_range_snapshots', 'weekly_opportunities_history',
    'feature_notify_optins'
  ];
BEGIN
  FOREACH tbl IN ARRAY tables LOOP
    BEGIN
      EXECUTE format('DELETE FROM %I WHERE user_id::text = $1', tbl) USING p_user_id::text;
    EXCEPTION
      WHEN undefined_table OR undefined_column THEN
        RAISE WARNING 'delete_user_data: skipped % for % — table/column schema unexpected (%)', tbl, p_user_id, SQLERRM;
    END;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION delete_user_data(UUID) TO service_role;


-- ===== 096_business_overview_snapshots.sql =====
-- ============================================================================
-- 096_business_overview_snapshots.sql
--
-- Diego, 2026-09-14 — /admin/overview showed only a same-day snapshot (total
-- users, MRR, DAU/WAU/MAU, etc.) with no way to see whether any of it is
-- trending up or down week over week. One row per day, aggregate business
-- metrics only — NOT per-user data, so this table is intentionally left out
-- of delete_user_data (there's no user_id column to delete by).
-- ============================================================================

CREATE TABLE IF NOT EXISTS business_overview_snapshots (
  snapshot_date            DATE PRIMARY KEY,
  total_users              INT NOT NULL,
  premium_count            INT NOT NULL,
  manual_comp_count        INT NOT NULL,
  trialing_count           INT NOT NULL,
  free_count               INT NOT NULL,
  signups_last_7d          INT NOT NULL,
  signups_last_30d         INT NOT NULL,
  -- Stripe fields nullable — a source outage on a given day shouldn't block
  -- the rest of the snapshot from being written (see snapshot_business_
  -- overview's docstring in business_overview_service.py).
  mrr_usd                  NUMERIC,
  active_subscriptions     INT,
  trialing_subscriptions   INT,
  cancellations_last_30d   INT,
  churn_rate_pct_30d       NUMERIC,
  dau                      INT,
  wau                      INT,
  mau                      INT,
  created_at               TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE business_overview_snapshots ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service: business overview snapshots" ON business_overview_snapshots;
CREATE POLICY "Service: business overview snapshots" ON business_overview_snapshots
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ===== 097_operating_costs.sql =====


-- ===== 098_welcome_card.sql =====
-- Migration 098: Premium welcome card — shown exactly once, right after
-- onboarding, announcing the 30-day free trial. Persisted server-side
-- (not localStorage) so it can genuinely never show again on any other
-- device, browser, or reinstall — Diego, 2026-09-16: "esto solo sale 1
-- vez en la vida y punto".
ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS has_seen_welcome_card BOOLEAN NOT NULL DEFAULT false;


-- ===== 099_backfill_welcome_card_existing_users.sql =====
-- Migration 099: Backfill has_seen_welcome_card for existing users.
--
-- Migration 098 added has_seen_welcome_card with DEFAULT false, which
-- applies to EVERY row, including accounts that existed long before the
-- welcome card feature shipped — so every existing user (Diego included)
-- started seeing it as if they were brand new, with a stale/irrelevant
-- trial_started_at from long ago driving the shown expiration date.
--
-- Confirmed live 2026-09-16: Diego saw his own account's old trial date
-- ("16 de septiembre") on a manual_comp permanent-premium account that
-- should never have a trial-expiration message at all.
--
-- This marks every account that already exists right now as "already
-- seen" — the card is meant for people signing up from today forward
-- only. Any row created AFTER this runs keeps has_seen_welcome_card's
-- column default (false) and sees the card exactly once, as intended.
UPDATE user_profiles
SET has_seen_welcome_card = true
WHERE has_seen_welcome_card = false;


-- ===== 100_premium_until.sql =====
-- Migration 100: premium_until — an explicit expiration date for Premium,
-- instead of recomputing it live from 3 different fields on every check.
--
-- Scope (Diego, 2026-09-16, after validating the current Stripe/webhook
-- flow): this is used ONLY for the two cases where no expiration is
-- stored anywhere today — a real paid Stripe subscription (set to the
-- period end on checkout/renewal, cleared implicitly since cancellation
-- already flips subscription_tier='free' via webhook) and a permanent
-- manual grant (explicitly NULL = never expires). The 30-day trial is
-- deliberately left untouched — it keeps using the existing, already-
-- audited-today trial_started_at + TRIAL_DAYS live calculation in
-- is_premium_active(), since that function is called from ~25 places and
-- flipping the trial's stored tier to "premium" would require every one
-- of them to also read/pass premium_until or risk treating an expired
-- trial as permanently premium.
--
-- NULL is the safe default for every existing row: a currently-paying
-- Stripe subscriber simply has no enforced expiration until their next
-- webhook event (renewal or cancellation) sets a real value — strictly
-- more permissive than today, never less, so this migration cannot
-- downgrade anyone on its own.
ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS premium_until TIMESTAMPTZ;


-- ===== 101_debt_fields.sql =====
-- Migration 101: debt/liabilities fields on user_profiles
--
-- Gap identified against the ARTHUR spec (§5 CONTEXTO FINANCIERO — pasivos):
-- decision_engine.py already has a comment admitting "NO HAY DATOS
-- ESTRUCTURADOS DE DEUDA EN NUVOS TODAVÍA" and silently treats debt as
-- unknown rather than zero. This adds a minimal, explicit place to store it
-- so Arthur can reason about it (opportunity cost of paying off debt vs.
-- investing, risk capacity for big life decisions) instead of always having
-- to ask or assume.
--
-- Deliberately minimal (has_debt + total amount), not a full liabilities
-- ledger (cards/loans/mortgage broken out) — that's a bigger feature than
-- this gap-fix warrants today. NULL/false is the safe default for every
-- existing row (no debt known, matches current behavior exactly).
ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS has_debt BOOLEAN,
  ADD COLUMN IF NOT EXISTS debt_amount_usd NUMERIC(14, 2);


-- ===== 102_decision_thesis.sql =====
-- Migration 102: investment decision thesis (motivo/expectativa/horizonte/convicción)
--
-- Gap identified against the ARTHUR spec (§7 MEMORIA DE DECISIONES): today
-- investment_decisions only logs a decision as a transaction (action,
-- ticker, price, a coarse trigger category) — not as a reasoned thesis
-- ("compró Nvidia porque esperaba crecimiento de ingresos y expansión de
-- márgenes"). This adds one flexible JSONB column, following the same
-- idiom as quiz_answers (migration 075), instead of a rigid set of typed
-- columns — the exact shape (motivo, expectativa, horizonte, convicción,
-- que_invalidaria_la_tesis) is enforced at the application layer, not the
-- DB, and only populated when the user actually states a reason — never
-- inferred/guessed to avoid extra per-message LLM extraction cost.
ALTER TABLE investment_decisions
  ADD COLUMN IF NOT EXISTS thesis JSONB;


-- ===== 103_pending_financial_actions.sql =====
-- Migration 103: pending_financial_actions
--
-- Backs Arthur's natural-language portfolio-transaction feature ("Compré
-- $200 de Google a $340"). Arthur's tool-calling loop is stateless between
-- user messages, so the "propose" step (parse the message into a
-- structured action, show a confirmation summary) needs somewhere durable
-- to hold that proposal until the user's NEXT message confirms or cancels
-- it — this table is that holding place, not a transaction ledger (the
-- real write still goes through user_portfolio via
-- apply_portfolio_positions in sync.py, reused as-is).
--
-- status transitions: pending -> applied | cancelled | expired.
-- A partial unique index enforces at most one 'pending' row per dedup_key,
-- so a duplicate/retried tool call from the same reported transaction
-- can't spawn two separate proposals (idempotency at the propose step;
-- applying twice is separately guarded by re-reading current shares at
-- confirm time).
CREATE TABLE IF NOT EXISTS pending_financial_actions (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id          TEXT NOT NULL,
  action_type      TEXT NOT NULL,              -- BUY_ASSET | SELL_ASSET
  portfolio_id     TEXT NOT NULL DEFAULT 'default',
  ticker           TEXT NOT NULL,
  quantity         NUMERIC(18, 6),
  amount           NUMERIC(14, 2),
  execution_price  NUMERIC(14, 4) NOT NULL,
  currency         TEXT NOT NULL DEFAULT 'USD',
  transaction_date DATE NOT NULL,
  notes            TEXT,
  raw_message      TEXT,                       -- the user's own words, for audit
  preview          JSONB,                      -- computed shares/avg-cost preview shown to the user
  dedup_key        TEXT NOT NULL,
  status           TEXT NOT NULL DEFAULT 'pending',
  source           TEXT NOT NULL DEFAULT 'USER_REPORTED_VIA_ARTHUR',
  created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  applied_at       TIMESTAMPTZ,
  expires_at       TIMESTAMPTZ NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_pfa_user_status ON pending_financial_actions (user_id, status);
CREATE UNIQUE INDEX IF NOT EXISTS idx_pfa_dedup_pending
  ON pending_financial_actions (dedup_key) WHERE status = 'pending';

-- user_id here is `text` (matches investment_decisions/user_portfolio), not
-- `uuid` — same cast convention as migration 019.
ALTER TABLE pending_financial_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users own pending financial actions" ON pending_financial_actions
  FOR ALL USING (auth.uid()::text = user_id);
CREATE POLICY "Service: pending financial actions" ON pending_financial_actions
  FOR ALL TO service_role USING (true);


-- ===== 104_pending_financial_actions_target_lot.sql =====
-- Migration 104: pending_financial_actions.target_lot_id
--
-- Extends the existing propose/confirm portfolio-transaction flow (migration
-- 103) to also cover corrections and deletions of an already-registered buy
-- lot ("me equivoqué, fueron 15 NVDA no 10" / "borra esa compra"). Lots now
-- carry a stable `id` (see add_buy_lot, sync.py) — this column is how a
-- pending UPDATE_TRANSACTION/DELETE_TRANSACTION action references which
-- lot it targets. NULL for the existing BUY_ASSET/SELL_ASSET action types,
-- which don't target an existing lot.
ALTER TABLE pending_financial_actions
  ADD COLUMN IF NOT EXISTS target_lot_id TEXT;


