-- ===== 106_phone_prompt.sql =====
-- Migration 106: one-time "add your phone number" prompt for EXISTING
-- users (new users already get asked during onboarding's phone step).
-- Diego, 2026-09-24: phone_number (along with `country`) is what
-- app/core/pricing_region.py's is_mexico() uses to decide whether to show
-- the MXN Stripe price instead of USD — Mexican debit cards frequently
-- decline USD charges, so a user this misses can genuinely fail to pay.
-- Persisted server-side (not localStorage), same "never twice, on any
-- device" pattern as has_seen_welcome_card (migration 098) — shown once
-- ever, whether the user fills it in or dismisses it.
ALTER TABLE user_profiles
  ADD COLUMN IF NOT EXISTS has_seen_phone_prompt BOOLEAN NOT NULL DEFAULT false;

-- Existing users who already have a phone number on file (from onboarding,
-- or manually added since) have nothing to gain from this prompt — mark
-- them as already-seen so it doesn't ask people who already answered.
UPDATE user_profiles
  SET has_seen_phone_prompt = true
  WHERE phone_number IS NOT NULL AND phone_number != '';


-- ===== 107_weekly_opportunities_snapshot.sql =====
-- Migration 107: store a real snapshot of what was actually picked/sent,
-- not just the ticker — Diego, 2026-09-24: "Cómo noooooo???? Si el domingo
-- me diste una lista de 5 posiciones" — the in-app Screener Semanal screen
-- was silently showing 0 results because it re-joined the sent tickers
-- against the CURRENT live undervalued-screener cache, which only holds
-- tickers that pass the margin-of-safety gate RIGHT NOW. A ticker's price
-- moving since Sunday (or the weekly cache simply refreshing since) drops
-- it out of that live list even though it was a completely real, valid
-- pick when it was sent. Persisting the full real pick at send time makes
-- the display permanently independent of what happens to the live
-- universe afterward.
ALTER TABLE weekly_opportunities_history
  ADD COLUMN IF NOT EXISTS snapshot JSONB;


-- ===== 108_usage_overage.sql =====
-- 108 — Uso extra (usage-based overage billing), Diego 2026-09-29.
--
-- One row per user per calendar month. Premium includes up to
-- settings.premium_price_usd * guard_protection_pct ($9) of real LLM cost;
-- past that the user either opts in to "uso extra" (billed in $4.99 USD /
-- $89 MXN blocks, one block per $2.50 of extra cost, capped at cap_blocks)
-- or keeps using Arthur on the cheaper model until the month resets.
--
-- blocks_billed / invoiced_at are written by worker.py's monthly billing
-- job so a month is never charged twice.

create table if not exists public.usage_overage (
    user_id        uuid        not null,
    period         text        not null,              -- 'YYYY-MM' (UTC)
    opted_in       boolean     not null default false,
    declined       boolean     not null default false,
    cap_blocks     integer     not null default 4 check (cap_blocks between 1 and 20),
    notified_level integer     not null default 0,    -- highest usage alert sent: 0/70/90/100
    blocks_billed  integer     not null default 0,
    invoiced_at    timestamptz,
    stripe_invoice_id text,
    created_at     timestamptz not null default now(),
    updated_at     timestamptz not null default now(),
    primary key (user_id, period)
);

alter table public.usage_overage enable row level security;

-- Users can read their own rows; all writes go through the backend
-- (service role), which bypasses RLS.
drop policy if exists "usage_overage_select_own" on public.usage_overage;
create policy "usage_overage_select_own" on public.usage_overage
    for select using (auth.uid() = user_id);

-- Speeds up llm_usage_log per-user monthly sums used by the usage meter.
create index if not exists idx_llm_usage_log_user_created
    on public.llm_usage_log (user_id, created_at);


-- ===== 109_arthur_proactive_and_imports.sql =====
-- 109 — Arthur proactivo + importación automática (Diego, 2026-09-29).
--
-- arthur_proactive_threads: conversations ARTHUR starts (from an alert,
-- an imported trade, a weekly review…). The opening message itself lives in
-- chat_history like any other message (same session_id), so it syncs to web
-- and mobile through the normal history/poll path; this table only tracks
-- which thread is new, its suggested actions, and when the user opened it.
create table if not exists public.arthur_proactive_threads (
    id          uuid primary key default gen_random_uuid(),
    user_id     text not null,
    session_id  text not null,
    category    text not null,
    title       text,
    message     text not null,
    actions     jsonb,
    created_at  timestamptz not null default now(),
    opened_at   timestamptz
);
create index if not exists idx_apt_user_created on public.arthur_proactive_threads (user_id, created_at desc);
alter table public.arthur_proactive_threads enable row level security;
drop policy if exists "apt_select_own" on public.arthur_proactive_threads;
create policy "apt_select_own" on public.arthur_proactive_threads for select using (auth.uid()::text = user_id);

-- inbound_email_aliases: each user's private forwarding address
-- (<alias>@<INBOUND_EMAIL_DOMAIN>) — brokers without an API (GBM,
-- Actinver…) email trade confirmations/statements; the user sets a mail
-- rule to forward them here once, and Nuvos updates the portfolio.
create table if not exists public.inbound_email_aliases (
    user_id    text primary key,
    alias      text not null unique,
    created_at timestamptz not null default now()
);
alter table public.inbound_email_aliases enable row level security;
drop policy if exists "iea_select_own" on public.inbound_email_aliases;
create policy "iea_select_own" on public.inbound_email_aliases for select using (auth.uid()::text = user_id);

-- inbound_imports: one row per received email / shared file, with what
-- was extracted and whether the user applied it.
create table if not exists public.inbound_imports (
    id           uuid primary key default gen_random_uuid(),
    user_id      text not null,
    source       text not null default 'email',   -- email | share
    sender       text,
    subject      text,
    kind         text,                            -- trades | statement | unknown
    payload      jsonb,                           -- {trades:[...], positions:[...], broker}
    status       text not null default 'parsed',  -- parsed | applied | dismissed | failed | nothing
    error        text,
    dedup_key    text,
    created_at   timestamptz not null default now(),
    applied_at   timestamptz
);
create index if not exists idx_inbound_imports_user on public.inbound_imports (user_id, created_at desc);
create unique index if not exists idx_inbound_imports_dedup on public.inbound_imports (user_id, dedup_key) where dedup_key is not null;
alter table public.inbound_imports enable row level security;
drop policy if exists "ii_select_own" on public.inbound_imports;
create policy "ii_select_own" on public.inbound_imports for select using (auth.uid()::text = user_id);


