-- ===== 111_macro_events_stable_identity.sql =====
-- ============================================================================
-- 111_macro_events_stable_identity.sql
--
-- Root cause being fixed: `event_id` (migration 074) was
-- sha1(event_type|event_name|event_date_utc) — derived from TWO fields FMP
-- regularly mutates for the exact same real-world release (the exact
-- release timestamp, on a reschedule; the raw label text, on a wording
-- tweak). Every time either changed, the next sync upserted a BRAND NEW
-- row instead of updating the existing one — the old row was never deleted
-- (no DELETE exists anywhere in this codebase for this table), so
-- Supabase silently accumulated duplicate rows for the same release, and
-- the read path (_collapse_moved_releases/_dedupe_rescheduled) had to
-- guess at render time which rows were really the same release.
--
-- Fix: `event_id` becomes a STABLE identity derived from the release's own
-- PERIOD (the thing that never changes about a release — "CPI for
-- September 2026" is always that, no matter what day FMP currently thinks
-- it posts on), computed by macro_calendar_service.event_period() from
-- FMP's own period suffix ("(Sep)", "(Oct/03)", "(Q3)") + a year inferred
-- from the release date — see that function's own docstring for the full
-- per-type breakdown. `event_id` keeps its existing TEXT UNIQUE column
-- (migration 074) — only what Python computes to put in it changes; no
-- column rename needed.
--
-- `event_period`: the human-readable period key itself ("2026-09",
-- "2026-Q3", "2026-10-28"), stored alongside event_id for auditability/
-- debugging and so a future caller never has to re-derive it.
--
-- `first_seen_at` / `last_seen_at`: `created_at`/`updated_at` already
-- existed but conflated two different ideas — `updated_at` doesn't tell
-- you whether FMP just RE-CONFIRMED an unchanged row or actually changed
-- a value. `first_seen_at` = when Nuvos first discovered this exact
-- release (set once, at INSERT, never touched again). `last_seen_at` =
-- the last time FMP's feed confirmed this release still exists (touched
-- on EVERY sync that sees it, changed value or not). `updated_at` keeps
-- its existing meaning (bumped only when a real field value changes).
--
-- Run AFTER 074. Safe to run multiple times (IF NOT EXISTS everywhere).
-- Does NOT touch existing rows' event_id/event_period — see
-- macro_calendar_service.backfill_stable_event_identity() (run once,
-- manually, after this migration) for that one-time, carefully-merged
-- consolidation of any pre-existing duplicate rows.
-- ============================================================================

BEGIN;

ALTER TABLE macro_economic_events
  ADD COLUMN IF NOT EXISTS event_period   TEXT,
  ADD COLUMN IF NOT EXISTS first_seen_at  TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS last_seen_at   TIMESTAMPTZ;

-- Backfill the two new timestamp columns for existing rows only (never
-- overwrites a value a later backfill/sync may have already set) — event_id
-- itself is NOT touched here; that's backfill_stable_event_identity()'s job,
-- since it requires the same period-inference logic macro_calendar_service.py
-- implements in Python, not something safely re-derivable in plain SQL.
UPDATE macro_economic_events
SET first_seen_at = COALESCE(first_seen_at, created_at),
    last_seen_at  = COALESCE(last_seen_at, updated_at)
WHERE first_seen_at IS NULL OR last_seen_at IS NULL;

ALTER TABLE macro_economic_events
  ALTER COLUMN first_seen_at SET DEFAULT NOW(),
  ALTER COLUMN last_seen_at  SET DEFAULT NOW();

CREATE INDEX IF NOT EXISTS idx_macro_economic_events_period ON macro_economic_events(event_type, event_period);

-- ── Lossless batch upsert ───────────────────────────────────────────────
-- Why an RPC instead of the backend's plain `.upsert(rows, on_conflict=
-- "event_id")`: PostgREST's upsert is a blind REPLACE of every column on
-- conflict — if FMP's current response has `actual: null` (not yet
-- released) for a release Supabase already has a real confirmed
-- actual_value for, a plain upsert would silently NULL out that confirmed
-- number. This function does the equivalent of ON CONFLICT DO UPDATE with
-- COALESCE(new, existing) on exactly the 4 "can go from real back to
-- unknown" fields (actual/estimate/previous/unit/speaker_name) — a real
-- new value always wins, but FMP temporarily omitting a field already on
-- file never erases it. event_date_utc/event_name/impact_* DO get
-- overwritten unconditionally — those are supposed to track FMP's current
-- answer (a reschedule, a label wording fix), not freeze at first-seen.
-- first_seen_at is set once (DEFAULT, untouched by the UPDATE branch);
-- last_seen_at bumps on every sync that reconfirms the row, regardless of
-- whether any value changed; updated_at only bumps when a real field
-- value actually changed, so it keeps meaning "last time THIS record's
-- data changed" the way the rest of the codebase already expects it to.
--
-- Takes the whole batch as one JSONB array so a full ~500-row sync is one
-- round trip and one atomic statement (safe under concurrent refreshes —
-- Postgres's own row-level locking on the unique index serializes two
-- concurrent calls touching the same event_id; whichever commits second
-- just sees the first's row as the pre-existing one and COALESCEs against
-- it, never loses data either way).
CREATE OR REPLACE FUNCTION upsert_macro_events_batch(p_rows JSONB)
RETURNS TABLE(event_id TEXT, was_insert BOOLEAN, value_changed BOOLEAN)
LANGUAGE plpgsql
AS $$
BEGIN
  RETURN QUERY
  WITH incoming AS (
    SELECT
      r->>'event_id'        AS event_id,
      r->>'event_type'      AS event_type,
      r->>'event_period'    AS event_period,
      r->>'event_name'      AS event_name,
      (r->>'event_date_utc')::TIMESTAMPTZ AS event_date_utc,
      COALESCE(r->>'country', 'US')        AS country,
      r->>'impact_source'   AS impact_source,
      r->>'impact_level'    AS impact_level,
      r->>'actual_value'    AS actual_value,
      r->>'estimate_value'  AS estimate_value,
      r->>'previous_value'  AS previous_value,
      r->>'unit'            AS unit,
      r->>'speaker_name'    AS speaker_name,
      COALESCE(r->>'source', 'fmp')         AS source
    FROM jsonb_array_elements(p_rows) AS r
  ),
  upserted AS (
    INSERT INTO macro_economic_events AS t (
      event_id, event_type, event_period, event_name, event_date_utc, country,
      impact_source, impact_level, actual_value, estimate_value, previous_value,
      unit, speaker_name, source, first_seen_at, last_seen_at, created_at, updated_at
    )
    SELECT
      i.event_id, i.event_type, i.event_period, i.event_name, i.event_date_utc, i.country,
      i.impact_source, i.impact_level, i.actual_value, i.estimate_value, i.previous_value,
      i.unit, i.speaker_name, i.source, NOW(), NOW(), NOW(), NOW()
    FROM incoming i
    ON CONFLICT (event_id) DO UPDATE SET
      event_period    = EXCLUDED.event_period,
      event_name      = EXCLUDED.event_name,
      event_date_utc  = EXCLUDED.event_date_utc,
      impact_source   = EXCLUDED.impact_source,
      impact_level    = EXCLUDED.impact_level,
      actual_value    = COALESCE(EXCLUDED.actual_value, t.actual_value),
      estimate_value  = COALESCE(EXCLUDED.estimate_value, t.estimate_value),
      previous_value  = COALESCE(EXCLUDED.previous_value, t.previous_value),
      unit            = COALESCE(EXCLUDED.unit, t.unit),
      speaker_name    = COALESCE(EXCLUDED.speaker_name, t.speaker_name),
      last_seen_at    = NOW(),
      updated_at      = CASE
        WHEN EXCLUDED.event_date_utc IS DISTINCT FROM t.event_date_utc
          OR EXCLUDED.event_name IS DISTINCT FROM t.event_name
          OR COALESCE(EXCLUDED.actual_value, t.actual_value) IS DISTINCT FROM t.actual_value
          OR COALESCE(EXCLUDED.estimate_value, t.estimate_value) IS DISTINCT FROM t.estimate_value
          OR COALESCE(EXCLUDED.previous_value, t.previous_value) IS DISTINCT FROM t.previous_value
        THEN NOW() ELSE t.updated_at
      END
    RETURNING t.event_id, (xmax = 0) AS was_insert, (t.updated_at = NOW()) AS value_changed
  )
  SELECT * FROM upserted;
END;
$$;

REVOKE ALL ON FUNCTION upsert_macro_events_batch(JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION upsert_macro_events_batch(JSONB) TO service_role;

COMMIT;


-- ===== 112_ibkr_flex_one_per_user.sql =====
-- ============================================================================
-- 112_ibkr_flex_one_per_user.sql
--
-- Root cause (confirmed live 2026-10-09): connect_ibkr_flex's upsert used
-- brokerage_connections' general UNIQUE(user_id, provider, institution_id)
-- constraint (migration 071's original schema — shared with Plaid, where
-- institution_id is a real different broker per row, so multiple rows per
-- user ARE correct there). For IBKR Flex, institution_id is the user's own
-- Flex Query ID — which a user can and does recreate (Diego did, when the
-- first query got stuck) — so reconnecting with a NEW query id upserted a
-- SECOND row instead of replacing the first. get_ibkr_flex_holdings then
-- called .maybe_single() expecting 0-1 rows, got 2, and PostgREST raised —
-- surfaced as a raw 500 "Internal server error" (an unhandled exception,
-- not one of this module's own HTTPExceptions).
--
-- Fix: a user has at most ONE IBKR Flex connection (same "one broker of
-- this kind at a time" assumption IOL already has, where institution_id is
-- always the fixed literal "iol"). This partial unique index lets
-- connect_ibkr_flex's upsert target (user_id, provider) instead — any
-- reconnect with a different query_id now updates the existing row rather
-- than creating a new one. Scoped to provider='ibkr_flex' only, so Plaid's
-- real multi-row-per-user case is completely unaffected.
--
-- Run AFTER first manually deleting any existing duplicate ibkr_flex rows
-- per user (the index creation fails otherwise) — see this migration's own
-- companion cleanup, already applied directly 2026-10-09 for the one
-- affected user found live.
-- ============================================================================

BEGIN;

CREATE UNIQUE INDEX IF NOT EXISTS idx_brokerage_connections_ibkr_flex_one_per_user
  ON brokerage_connections (user_id, provider)
  WHERE provider = 'ibkr_flex';

COMMIT;


-- ===== 113_cash_holdings_idempotency.sql =====
-- Migration 113: idempotency key for cash_holdings inserts
--
-- "Agregar efectivo" had no protection against a double-submit (double
-- click, or the frontend's own 3x retry racing a request that actually
-- already succeeded) creating two rows for the same add. The client now
-- sends a stable client-generated UUID per add attempt; a unique
-- constraint on (user_id, client_id) makes a repeated POST with the same
-- key a no-op instead of a duplicate holding. NULL client_id (older
-- clients) is unconstrained, same as before.

ALTER TABLE cash_holdings ADD COLUMN IF NOT EXISTS client_id UUID;

CREATE UNIQUE INDEX IF NOT EXISTS idx_cash_holdings_user_client
  ON cash_holdings (user_id, client_id)
  WHERE client_id IS NOT NULL;


-- ===== 114_company_valuations.sql =====
-- Migration 114: durable, versioned persistence of Nuvos Radar's computed
-- intrinsic valuations — Supabase becomes the source of truth; Redis stays
-- as a fast-path cache in front of it, not the only copy.
--
-- Applied 2026-10-20/21 — confirmed live in production (157 rows as of
-- 2026-10-21; re-running this file now fails on "policy already exists",
-- which is expected and not a problem). Shared platform data (not
-- per-user), mirrors macro_calendar's public-read RLS pattern rather than
-- cash_holdings' per-user one.

CREATE TABLE IF NOT EXISTS company_valuations (
  id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ticker                  TEXT NOT NULL,
  intrinsic_value_usd     NUMERIC,
  currency                TEXT NOT NULL DEFAULT 'USD',
  -- Which model actually produced this number — GQV dual-track, REIT
  -- FFO/AFFO, financial-sector, legacy P/E/relative fallback, etc. Must
  -- always reflect the real sector-aware routing already in
  -- fundamental_analysis_service.py — never a single generic label.
  methodology             TEXT NOT NULL,
  -- Mirrors the existing Redis cache-key version-bump convention
  -- (company_diagnostic:v10:...) — a row computed by an older model
  -- version is recognizably stale once the app's version advances.
  model_version           TEXT NOT NULL,
  -- The fiscal period actually used (e.g. "2026-Q2"), from the same
  -- _latest_reported_earnings_period() signal the app already computes —
  -- NOT the calendar date of the run.
  financial_report_period TEXT,
  computed_at             TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  -- Real inputs used for this specific computation (discount rate, growth
  -- assumptions, scenario bounds) — an audit trail, not displayed as-is.
  assumptions             JSONB,
  validation_status       TEXT NOT NULL CHECK (validation_status IN ('valid', 'insufficient_data', 'failed')),
  error_detail            TEXT,
  -- TRUE marks the row a ticker's screen should read today. A 'failed'
  -- (transient fetch/compute error) row can NEVER be current — it's a log
  -- entry only, and the previous valid/insufficient_data row stays active
  -- untouched. This is enforced by the CHECK below, not just app
  -- discipline, so a bug can't silently promote an error into "the truth."
  is_current              BOOLEAN NOT NULL DEFAULT TRUE,
  CHECK (NOT (validation_status = 'failed' AND is_current)),
  created_at               TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 2026-10-20, compatibility review before applying: dropped the
-- originally-drafted `in_progress_since` column — "is a ticker's
-- recompute already running" is a coordination concern, not data of
-- record, and this codebase already has a proven, self-expiring,
-- cross-process-safe primitive for exactly that
-- (app/core/cache.py's acquire_lock/release_lock, TTL-based, reused
-- as-is by company_valuation_service.py rather than a new DB-backed
-- claim column that would need its own staleness logic re-invented).

-- Exactly one current row per ticker at a time; every prior computation
-- (valid or not) stays in the table as history, is_current = FALSE.
CREATE UNIQUE INDEX IF NOT EXISTS idx_company_valuations_current
  ON company_valuations (ticker) WHERE is_current;

CREATE INDEX IF NOT EXISTS idx_company_valuations_ticker_computed
  ON company_valuations (ticker, computed_at DESC);

ALTER TABLE company_valuations ENABLE ROW LEVEL SECURITY;

-- Shared read-only data for every signed-in/guest screen, same pattern as
-- macro_calendar_events — no per-user ownership concept here.
CREATE POLICY company_valuations_read_all ON company_valuations
  FOR SELECT USING (true);

-- No INSERT/UPDATE/DELETE policy for anon/authenticated roles: writes only
-- ever happen through the backend's service_role key, which bypasses RLS
-- entirely (same caveat as cash_holdings/dividend_income — see the
-- 2026-10-20 cash/dividends audit).

-- Atomic "make this the new current valuation" — a plain two-step
-- UPDATE-then-INSERT from application code would have a real window
-- where a crash between the two calls leaves the ticker with NO current
-- row at all (the old one already flipped false, the new one never
-- landed). Wrapping both in one function means they commit or roll back
-- together. Never called for validation_status='failed' — that path is
-- a plain INSERT with is_current=false from the service, no flip needed,
-- so a failed computation can never touch the last valid row.
CREATE OR REPLACE FUNCTION set_current_company_valuation(
  p_ticker TEXT,
  p_intrinsic_value_usd NUMERIC,
  p_currency TEXT,
  p_methodology TEXT,
  p_model_version TEXT,
  p_financial_report_period TEXT,
  p_assumptions JSONB,
  p_validation_status TEXT
) RETURNS company_valuations
LANGUAGE plpgsql
AS $$
DECLARE
  v_row company_valuations;
BEGIN
  IF p_validation_status NOT IN ('valid', 'insufficient_data') THEN
    RAISE EXCEPTION 'set_current_company_valuation: validation_status must be valid or insufficient_data, got %', p_validation_status;
  END IF;

  UPDATE company_valuations SET is_current = FALSE
    WHERE ticker = p_ticker AND is_current = TRUE;

  INSERT INTO company_valuations (
    ticker, intrinsic_value_usd, currency, methodology, model_version,
    financial_report_period, assumptions, validation_status, is_current
  ) VALUES (
    p_ticker, p_intrinsic_value_usd, p_currency, p_methodology, p_model_version,
    p_financial_report_period, p_assumptions, p_validation_status, TRUE
  ) RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


-- ===== 115_company_valuations_backfill_tracking.sql =====
-- Migration 115: resumable-backfill tracking columns for company_valuations.
--
-- Purely additive (nullable columns, no data migration, no RLS change) —
-- the existing live read path (get_persisted_valuation, the
-- /company-diagnostic route) never reads these, so this cannot change
-- any existing behavior. Exists only so the new backfill job
-- (job_backfill_company_valuations_batch, worker.py) can tell "never
-- attempted" apart from "attempted recently and failed, back off before
-- retrying" apart from "attempted long enough ago, eligible for retry"
-- without re-deriving that from the `failed` history rows on every tick
-- (which would mean an unbounded, ever-growing table scan as history
-- accumulates).
--
-- Rollback: DROP COLUMN each of these three — no CHECK/index/function
-- depends on them, so this is safe to revert at any time without
-- touching the migration-114 schema it builds on.

ALTER TABLE company_valuations
  ADD COLUMN IF NOT EXISTS attempt_count INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS last_attempt_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS next_retry_at TIMESTAMPTZ;

-- Only ever read against the current row per ticker — same partial-index
-- shape as migration 114's own idx_company_valuations_current.
CREATE INDEX IF NOT EXISTS idx_company_valuations_current_retry
  ON company_valuations (next_retry_at) WHERE is_current;


-- ===== 115_fix_upsert_macro_events_ambiguous_column.sql =====
-- ============================================================================
-- 115_fix_upsert_macro_events_ambiguous_column.sql
--
-- Root cause found 2026-10-21, confirmed live against production (called
-- the RPC directly 3 times — empty payload, a synthetic row, a real-world
-- row — all 3 failed identically):
--
--   Error 42702: column reference "event_id" is ambiguous
--   Details: It could refer to either a PL/pgSQL variable or a table
--   column.
--
-- Migration 111's `upsert_macro_events_batch` declares
-- `RETURNS TABLE(event_id TEXT, ...)`, which implicitly creates a
-- PL/pgSQL variable named `event_id` in scope for the whole function
-- body — colliding with macro_economic_events' own `event_id` column
-- every time it's referenced unqualified inside the embedded SQL (the
-- INSERT's ON CONFLICT target list and column list). The RPC has been
-- throwing this on EVERY call since the day migration 111 shipped
-- (2026-10-04), silently caught by _upsert_rows_lossless's except block
-- and falling back to a plain `.upsert()` — which does NOT have the
-- COALESCE loss-protection on actual/estimate/previous_value/unit/
-- speaker_name that was the entire point of migration 111, and never
-- advances first_seen_at/last_seen_at. A field that should stay at its
-- last confirmed real value can get silently blanked by a transient null
-- from FMP — "a veces los eventos... no se muestran correctamente."
--
-- Fix: rename the colliding OUT parameter to `out_event_id` so no
-- identifier in the function body can mean both the variable and the
-- table column. Everything else is unchanged — the Python caller
-- (_upsert_rows_lossless) only ever reads `was_insert` off each returned
-- row, never `event_id`, so this rename needs no application code change.
-- ============================================================================

BEGIN;

-- CREATE OR REPLACE cannot change a function's OUT-parameter names (only
-- the body) — Postgres requires DROP + CREATE for that, which is exactly
-- what renaming the colliding `event_id` OUT param to `out_event_id`
-- needs to do.
DROP FUNCTION IF EXISTS upsert_macro_events_batch(JSONB);

CREATE FUNCTION upsert_macro_events_batch(p_rows JSONB)
RETURNS TABLE(out_event_id TEXT, was_insert BOOLEAN, value_changed BOOLEAN)
LANGUAGE plpgsql
AS $$
BEGIN
  RETURN QUERY
  WITH incoming AS (
    SELECT
      r->>'event_id'        AS event_id,
      r->>'event_type'      AS event_type,
      r->>'event_period'    AS event_period,
      r->>'event_name'      AS event_name,
      (r->>'event_date_utc')::TIMESTAMPTZ AS event_date_utc,
      COALESCE(r->>'country', 'US')        AS country,
      r->>'impact_source'   AS impact_source,
      r->>'impact_level'    AS impact_level,
      r->>'actual_value'    AS actual_value,
      r->>'estimate_value'  AS estimate_value,
      r->>'previous_value'  AS previous_value,
      r->>'unit'            AS unit,
      r->>'speaker_name'    AS speaker_name,
      COALESCE(r->>'source', 'fmp')         AS source
    FROM jsonb_array_elements(p_rows) AS r
  ),
  upserted AS (
    INSERT INTO macro_economic_events AS t (
      event_id, event_type, event_period, event_name, event_date_utc, country,
      impact_source, impact_level, actual_value, estimate_value, previous_value,
      unit, speaker_name, source, first_seen_at, last_seen_at, created_at, updated_at
    )
    SELECT
      i.event_id, i.event_type, i.event_period, i.event_name, i.event_date_utc, i.country,
      i.impact_source, i.impact_level, i.actual_value, i.estimate_value, i.previous_value,
      i.unit, i.speaker_name, i.source, NOW(), NOW(), NOW(), NOW()
    FROM incoming i
    ON CONFLICT (event_id) DO UPDATE SET
      event_period    = EXCLUDED.event_period,
      event_name      = EXCLUDED.event_name,
      event_date_utc  = EXCLUDED.event_date_utc,
      impact_source   = EXCLUDED.impact_source,
      impact_level    = EXCLUDED.impact_level,
      actual_value    = COALESCE(EXCLUDED.actual_value, t.actual_value),
      estimate_value  = COALESCE(EXCLUDED.estimate_value, t.estimate_value),
      previous_value  = COALESCE(EXCLUDED.previous_value, t.previous_value),
      unit            = COALESCE(EXCLUDED.unit, t.unit),
      speaker_name    = COALESCE(EXCLUDED.speaker_name, t.speaker_name),
      last_seen_at    = NOW(),
      updated_at      = CASE
        WHEN EXCLUDED.event_date_utc IS DISTINCT FROM t.event_date_utc
          OR EXCLUDED.event_name IS DISTINCT FROM t.event_name
          OR COALESCE(EXCLUDED.actual_value, t.actual_value) IS DISTINCT FROM t.actual_value
          OR COALESCE(EXCLUDED.estimate_value, t.estimate_value) IS DISTINCT FROM t.estimate_value
          OR COALESCE(EXCLUDED.previous_value, t.previous_value) IS DISTINCT FROM t.previous_value
        THEN NOW() ELSE t.updated_at
      END
    RETURNING t.event_id, (xmax = 0) AS was_insert, (t.updated_at = NOW()) AS value_changed
  )
  SELECT * FROM upserted;
END;
$$;

REVOKE ALL ON FUNCTION upsert_macro_events_batch(JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION upsert_macro_events_batch(JSONB) TO service_role;

COMMIT;


-- ===== 116_company_valuations_under_review_status.sql =====
-- Migration 116: a 4th validation_status, 'under_review' — for a
-- computation that completed successfully (not a fetch/calc failure) but
-- tripped an automated anomaly guard (e.g. an operating-margin anchor
-- built from a thin mixed-regime trend, or an intrinsic-value/price gap
-- far outside this universe's normal range) and must not present as a
-- trustworthy `valid` number until a human reviews it.
--
-- Real case this exists for: AXON's 2026-10-27 backfill-pilot run
-- published $36.30 vs. a $425.87 real price (0.085x, vs. 0.7-0.9x for
-- every other ticker in the pilot) — root-caused to operating_margin_
-- anchor being computed from a genuinely mixed-sign, SBC-distorted
-- 5-year trend (see fundamental_analysis_service.py's
-- operating_margin_anchor_reliable flag, added in the same change as
-- this migration). The row stays queryable, with its real computed
-- number and assumptions intact — this is a presentation/trust flag,
-- never a deletion or a correction of the number itself.
--
-- Purely additive: widens the existing CHECK constraints and the RPC's
-- allowed values; no existing row changes shape, no index changes.
--
-- Rollback: re-run migration 114's original CHECK/RPC definitions (the
-- two ALTER/CREATE OR REPLACE statements below are themselves idempotent
-- supersets, so reverting means restoring the narrower lists, not
-- undoing a destructive change — see the inline comments below for the
-- exact prior text).

-- Was: CHECK (validation_status IN ('valid', 'insufficient_data', 'failed'))
-- Dropped by querying the catalog rather than a hardcoded name, since the
-- original constraint was declared inline on the column (migration 114)
-- and Postgres auto-names those — safer than guessing the generated name.
DO $$
DECLARE
  c RECORD;
BEGIN
  FOR c IN
    SELECT con.conname
    FROM pg_constraint con
    JOIN pg_class rel ON rel.oid = con.conrelid
    WHERE rel.relname = 'company_valuations'
      AND con.contype = 'c'
      AND pg_get_constraintdef(con.oid) ILIKE '%validation_status%IN%'
  LOOP
    EXECUTE format('ALTER TABLE company_valuations DROP CONSTRAINT %I', c.conname);
  END LOOP;
END $$;

ALTER TABLE company_valuations ADD CONSTRAINT company_valuations_validation_status_check
  CHECK (validation_status IN ('valid', 'insufficient_data', 'failed', 'under_review'));

-- Was: CHECK (NOT (validation_status = 'failed' AND is_current)) — unchanged,
-- 'under_review' is allowed to be is_current (same as 'insufficient_data':
-- it's a real completed computation, just not a trustworthy one yet, and
-- the ticker's page should still show whatever it has rather than nothing).

CREATE OR REPLACE FUNCTION set_current_company_valuation(
  p_ticker TEXT,
  p_intrinsic_value_usd NUMERIC,
  p_currency TEXT,
  p_methodology TEXT,
  p_model_version TEXT,
  p_financial_report_period TEXT,
  p_assumptions JSONB,
  p_validation_status TEXT
) RETURNS company_valuations
LANGUAGE plpgsql
AS $$
DECLARE
  v_row company_valuations;
BEGIN
  -- Was: IF p_validation_status NOT IN ('valid', 'insufficient_data') THEN
  IF p_validation_status NOT IN ('valid', 'insufficient_data', 'under_review') THEN
    RAISE EXCEPTION 'set_current_company_valuation: validation_status must be valid, insufficient_data, or under_review, got %', p_validation_status;
  END IF;

  UPDATE company_valuations SET is_current = FALSE
    WHERE ticker = p_ticker AND is_current = TRUE;

  INSERT INTO company_valuations (
    ticker, intrinsic_value_usd, currency, methodology, model_version,
    financial_report_period, assumptions, validation_status, is_current
  ) VALUES (
    p_ticker, p_intrinsic_value_usd, p_currency, p_methodology, p_model_version,
    p_financial_report_period, p_assumptions, p_validation_status, TRUE
  ) RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


-- ===== 116_fix_brk_dual_class_ticker_split.sql =====
-- ============================================================================
-- 116_fix_brk_dual_class_ticker_split.sql
--
-- One-time data fix, 2026-10-21 (Nuvos Radar structural audit). Before
-- app/services/company_valuation_service.py's ticker normalization was
-- unified with the route layer's (screener._resolve_quick_ticker), a
-- caller writing "BRK.B" literally (bypassing the route's dot->hyphen
-- fix) created a SEPARATE current row from the real "BRK-B" row — both
-- "current" simultaneously, since they're different primary-key strings
-- to Postgres (confirmed live: BRK-B valid $751.86, BRK.B
-- insufficient_data, both is_current=true).
--
-- Going forward every writer normalizes to the hyphen form, so "BRK.B"
-- should never be written/read as a key again — this just demotes the
-- orphaned "BRK.B" row(s) to history (is_current=false), the same thing
-- that would have happened automatically if they'd shared one key all
-- along. NOTHING is deleted — full audit trail preserved, exactly the
-- "sin eliminar historial por accidente" requirement.
--
-- Idempotent: a second run has nothing left to update (WHERE clause only
-- ever matches literal "BRK.B"/"BF.B"-style dotted keys that are still
-- marked current).
-- ============================================================================

BEGIN;

UPDATE company_valuations
SET is_current = FALSE
WHERE is_current = TRUE
  AND ticker ~ '\.[A-Z]$';  -- any dotted dual-class key (BRK.B, BF.B, ...) still marked current

COMMIT;


-- ===== 117_company_valuations_full_snapshot.sql =====
-- Migration 117: full diagnostic snapshot persistence for company_valuations.
--
-- Why: migrations 114-116 persist the NUMERIC valuation (intrinsic value,
-- scenario bounds, validation status) but not the full rich diagnostic the
-- frontend actually renders (score, pillar scores, competitor comparison,
-- sector comparison, PE waterfall, fair-PE breakdown, narrative fields,
-- etc. — see frontend/web/src/lib/types/companyDiagnostic.ts, ~30
-- top-level fields). Today, when a read falls back to the persisted row
-- (_degraded_diagnostic in screener.py), it can only reconstruct a
-- CUT-DOWN ficha (price + fair value band, nothing else) — not the full
-- experience a user would see on a live-computed open. This column lets
-- the fallback path serve the exact same rich ficha the user would have
-- seen live, with zero recomputation and zero external-provider calls.
--
-- Purely additive: 2 nullable columns, no existing column/constraint/
-- index/RPC changes, no data migration. Old rows (without a snapshot)
-- keep working exactly as today via the existing cut-down reconstruction
-- in _degraded_diagnostic — this is a read enhancement, not a read
-- requirement.
--
-- Rollback: DROP COLUMN both — nothing else references them.

ALTER TABLE company_valuations
  ADD COLUMN IF NOT EXISTS diagnostic_snapshot JSONB,
  -- Mirrors the existing Redis _DIAGNOSTIC_SCHEMA_VERSION convention
  -- (screener.py) — a snapshot shaped by an older frontend contract is
  -- recognizably stale once that version advances, same "treat as miss,
  -- not as a crash" discipline already used for the Redis cache.
  ADD COLUMN IF NOT EXISTS snapshot_schema_version INTEGER;

-- Read pattern is always "give me the current row for this ticker" (same
-- as every existing query against this table) — no new index needed,
-- idx_company_valuations_current (migration 114) already covers it.


-- ===== 117_subscription_audit_log.sql =====
-- ============================================================================
-- 117_subscription_audit_log.sql
--
-- Diego, 2026-10-26: "quién (tú, Stripe, un cron) cambió el plan de cada
-- usuario y cuándo" — after repeatedly hitting "por qué cambió a Free sin
-- que yo lo tocara" (manual_comp downgrade bug, the Oct 21-22 lapsed-
-- premium_until incident) with no way to answer it except grepping
-- Railway logs, every write site that changes a user's subscription_tier/
-- subscription_source/premium_until now also writes one row here — see
-- app/services/subscription_audit.py.
--
-- Deliberately append-only and minimal: no "old value" column. The
-- previous row for the same user IS the old value — a chronological feed
-- per user already tells the whole story without duplicating state that
-- can drift from the real one in user_profiles.
--
-- `premium_until` here is NULL whenever that specific write didn't touch
-- the column (e.g. a plain tier downgrade) — NOT evidence it was cleared.
-- Compare against the next row's premium_until (or user_profiles' current
-- value) for "what is it now," not this column alone.
-- ============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS subscription_audit_log (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  actor           TEXT NOT NULL,   -- e.g. "admin:diego@...", "stripe_webhook:checkout.session.completed", "stripe_self_heal"
  tier            TEXT,            -- subscription_tier this write set, if any
  source          TEXT,            -- subscription_source this write set, if any
  premium_until   TIMESTAMPTZ,     -- premium_until this write set, if any (see note above)
  reason          TEXT,            -- short human-readable context
  created_at      TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_sub_audit_user     ON subscription_audit_log(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_sub_audit_created   ON subscription_audit_log(created_at DESC);

ALTER TABLE subscription_audit_log ENABLE ROW LEVEL SECURITY;
-- No SELECT/INSERT policy for the anon/authenticated roles on purpose —
-- this is an admin-only trail, read and written exclusively via the
-- backend's service-role key (which bypasses RLS), the same way
-- notification_analytics has no user-facing policy either.

COMMIT;


-- ===== 118_system_event_log.sql =====
-- ============================================================================
-- 118_system_event_log.sql
--
-- Diego, 2026-10-26: "un panel de salud del sistema... en vez de enterarte
-- por quejas de usuarios o porque yo lo encuentro buceando en Railway."
--
-- Generic, append-only log for background-job/system failures that aren't
-- already captured elsewhere. Pushes themselves are NOT logged here —
-- notification_log (migration 011) already records every send attempt
-- with status in ('sent','failed','skipped'), so the health panel reads
-- that table directly instead of duplicating it.
--
-- What IS new here, written by app/services/system_health.py:
--   - "broker_sync_failed"  — job_sync_connected_brokers per-user/provider
--     failure (Plaid/IOL/IBKR Flex)
--   - "arthur_fallback"     — Arthur's primary model + Haiku retry both
--     failed and the chat fell through to the generic GPT-mini answer
--   - "arthur_total_failure" — even the generic fallback failed (user got
--     a 503)
--
-- This only has data from the moment it's deployed forward — there is no
-- historical backfill, by nature of being a new log.
-- ============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS system_event_log (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_type  TEXT NOT NULL,
  detail      TEXT,
  user_id     UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at  TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_sys_event_type_created ON system_event_log(event_type, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_sys_event_created       ON system_event_log(created_at DESC);

ALTER TABLE system_event_log ENABLE ROW LEVEL SECURITY;
-- Admin-only, same as subscription_audit_log — no user-facing policy,
-- read/written exclusively via the backend's service-role key.

COMMIT;


-- ===== 119_company_valuation_review_log.sql =====
-- Migration 119: company_valuation_reviews — audit trail for under_review
-- tickers, 2026-10-29 scaling-review design.
--
-- Why a new table instead of a JSONB sub-object on company_valuations.
-- assumptions/diagnostic_snapshot: those two fields are OVERWRITTEN on
-- every recompute (set_current_company_valuation does an INSERT with
-- is_current flip, never an in-place UPDATE of history) — any field
-- nested there is a snapshot of "what the code computed this run", not
-- a durable human decision log. A review decision ("I checked this,
-- it's a real methodology gap, approved 2026-11-02 by Diego") must
-- survive the next automated recompute attempt untouched, and must be
-- queryable across the whole history of a ticker, not just its current
-- row — that's a distinct lifecycle from the valuation data itself, so
-- it gets its own table, same reasoning that gave subscription changes
-- their own audit_log table rather than a column on `users`.
--
-- Purely additive: one new table, no changes to company_valuations's
-- existing columns/constraints/RPC. Nothing reads this table yet except
-- a future admin panel and manual queries — it does not change any
-- current runtime behavior.
--
-- Rollback: DROP TABLE company_valuation_reviews — nothing else
-- references it.

CREATE TABLE IF NOT EXISTS company_valuation_reviews (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ticker              TEXT NOT NULL,
  -- One of the Paso 2 categories — CHECK keeps this from drifting into
  -- free-text buckets that can't be aggregated/reported on later.
  category            TEXT NOT NULL CHECK (category IN (
                         'data_inconsistency',
                         'unreliable_anchor',
                         'methodology_mismatch',
                         'extreme_price_gap_unexplained',
                         'insufficient_evidence'
                       )),
  -- Free-text detail — the specific reason, same content today's
  -- error_detail column already carries, duplicated here so it survives
  -- a future recompute that might change/clear error_detail.
  detected_reason     TEXT NOT NULL,
  detected_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- 'open' | 'investigating' | 'resolved_valid' | 'resolved_methodology_fix'
  -- | 'resolved_data_fix' | 'wont_fix_stays_under_review'. Only a human
  -- (via whatever future admin action writes this row) may set a
  -- resolved_* status — no code path in this migration or elsewhere
  -- auto-writes one, by design (Paso 3's policy: no automatic
  -- valid promotion just because the market-price gap shrinks).
  status              TEXT NOT NULL DEFAULT 'open' CHECK (status IN (
                         'open', 'investigating', 'resolved_valid',
                         'resolved_methodology_fix', 'resolved_data_fix',
                         'wont_fix_stays_under_review'
                       )),
  -- Numbers worth keeping alongside the row even though they also live
  -- in company_valuations at the time of detection — company_valuations
  -- keeps getting overwritten; this is the frozen "as first flagged" view.
  intrinsic_value_usd NUMERIC,
  price_at_detection  NUMERIC,
  ratio_at_detection  NUMERIC,
  methodology         TEXT,
  evidence            JSONB,              -- freeform: FCF/SBC/debt/shares backing the finding
  next_action         TEXT,
  resolved_by         TEXT,               -- human identifier (email), set only alongside a resolved_* status
  resolved_at         TIMESTAMPTZ,
  resolution_rationale TEXT,              -- required in practice (enforce in app code) whenever resolved_*
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_company_valuation_reviews_ticker
  ON company_valuation_reviews (ticker, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_company_valuation_reviews_open
  ON company_valuation_reviews (status) WHERE status IN ('open', 'investigating');

-- RLS: same public-read-admin-write posture as company_valuations and
-- macro_calendar_events — read is safe to expose (it's an explanation,
-- not sensitive), writes are backend-service-key only (the app always
-- queries through the service-role key; this just blocks any direct
-- anon-key path).
ALTER TABLE company_valuation_reviews ENABLE ROW LEVEL SECURITY;

CREATE POLICY company_valuation_reviews_public_read
  ON company_valuation_reviews FOR SELECT
  USING (true);


-- ===== 120_price_alerts_target_range.sql =====
-- Migration 120: price_alerts range support ("Mi Precio Objetivo"),
-- 2026-11-05.
--
-- Why: the existing price_alerts table (032_rls_hardening.sql) only
-- supports a single above/below threshold, and feeds a dead code path
-- — check_custom_price_alerts() / scan_and_notify_all_users() /
-- run_notifications() (backend/app/services/notification_service.py)
-- is defined but never scheduled or called anywhere in worker.py
-- (confirmed by repo-wide grep, 2026-11-05). This migration extends
-- the table to also store a true price RANGE (target_price = low
-- bound, new target_price_high = high bound, condition = 'range'),
-- for the stock-detail "Mi Precio Objetivo" widget. 'above'/'below'
-- are kept for backward compat with the existing subvaluadas "Mi Zona
-- de Compra" feature (FollowAlertPanel.tsx), which only ever writes
-- condition='below'.
--
-- UNIQUE(user_id, ticker) is kept as-is — a user gets exactly one
-- active target per ticker, the same invariant the table already
-- enforced. Saving a "Mi Precio Objetivo" range for a ticker that
-- already has a subvaluadas 'below' alert overwrites that row — same
-- behavior the table already has between re-saves of the same alert
-- type, just now also across alert types. Deliberate: both features
-- share the same table/row by design.
--
-- Rollback:
--   ALTER TABLE price_alerts DROP CONSTRAINT IF EXISTS price_alerts_range_bounds_check;
--   ALTER TABLE price_alerts DROP CONSTRAINT IF EXISTS price_alerts_condition_check;
--   ALTER TABLE price_alerts ADD CONSTRAINT price_alerts_condition_check
--     CHECK (condition IN ('above', 'below'));
--   ALTER TABLE price_alerts DROP COLUMN IF EXISTS target_price_high;
--   (Any existing condition='range' rows must be deleted/migrated BEFORE
--   re-adding the narrower CHECK, or the ALTER will fail.)

ALTER TABLE price_alerts ADD COLUMN IF NOT EXISTS target_price_high NUMERIC NULL;

ALTER TABLE price_alerts DROP CONSTRAINT IF EXISTS price_alerts_condition_check;
ALTER TABLE price_alerts ADD CONSTRAINT price_alerts_condition_check
  CHECK (condition IN ('above', 'below', 'range'));

-- Guard: a 'range' row must always carry both bounds, low < high.
ALTER TABLE price_alerts DROP CONSTRAINT IF EXISTS price_alerts_range_bounds_check;
ALTER TABLE price_alerts ADD CONSTRAINT price_alerts_range_bounds_check
  CHECK (
    condition != 'range'
    OR (target_price_high IS NOT NULL AND target_price_high > target_price)
  );

